INSERT INTO lengua (nombre_completo, modalidad)
INSERT INTO tipo_sena (tipo) VALUES ('SM'), ('SB'), ('SS'), ('SC') ON CONFLICT (tipo) DO NOTHING;
INSERT INTO diccionario (completo, autor)
INSERT INTO dlsm_entrada (n, tipo, fono, palabras, definicion) VALUES
(1, 'SB', '{"codigo": "B-P 1", "significado": "¿Por qué?", "tipo_sena": "SB", "configuracion": "MD seña que pasa de B-P.2 a 1.1, MB S.1", "orientacion": "MD la palma inicia hacia abajo y termina hacia arriba, MB palma hacia afuera .", "ubicacion": "La MD inicia sobre MB y termina a la altura de los hombros; MB a la altura del pecho.", "movimiento": "MD recto y después la mano se agita.", "rasgos_no_manuales": "Ceño fruncido, boca semiabierta.", "definicion": "loc. adv. Por cuál razón, causa o motivo.", "pagina": 1}', ARRAY['¿Por qué?']::text[], 'loc. adv. Por cuál razón, causa o motivo.'),
(2, 'SM', '{"codigo": "B-P 2", "significado": "¿Qué onda?", "tipo_sena": "SM", "configuracion": "B-P.7", "orientacion": "Palma hacia abajo.", "ubicacion": "A la altura de la nariz, del lado derecho al izquierdo.", "movimiento": "La mano sigue una trayectoria ondulada.", "rasgos_no_manuales": "Cabeza inclinada, se esboza una sonrisa.", "definicion": "loc. adv. Frase coloquial para preguntar a nuestro interlocutor cómo está.", "pagina": 1}', ARRAY['¿Qué onda?']::text[], 'loc. adv. Frase coloquial para preguntar a nuestro interlocutor cómo está.'),
(3, 'SC', '{"codigo": "B-P 3", "significado": "¿Y eso?", "tipo_sena": "SC: I. SM; II. SB", "configuracion": "I. B-P.2; II. MD y MB 1.1", "orientacion": "I. y II. Palmas hacia adentro.", "ubicacion": "I. La mano inicia sobre el pecho y se desliza hacia enfrente; II. Del pecho al rostro.", "movimiento": "I. La mano se mueve formando un arco; II. MD y MB recto alternadamente.", "rasgos_no_manuales": "Cejas hacia arriba, comisuras de los labios ligeramente hacia abajo.", "definicion": "loc. adv. Frase coloquial para preguntar a nuestro interlocutor por qué razón ocurre alguna situación.", "nota_cultural": "La seña se emplea después de una ofensa como respuesta.", "pagina": 1}', ARRAY['¿Y eso?']::text[], 'loc. adv. Frase coloquial para preguntar a nuestro interlocutor por qué razón ocurre alguna situación.'),
(4, 'SB', '{"codigo": "B-P 4", "significado": "Abajo – Debajo", "tipo_sena": "SB", "configuracion": "MD y MB B-P.6", "orientacion": "MD y MB palmas hacia abajo.", "ubicacion": "MD inicia sobre MB y termina a la altura de la cintura, MB a la altura del pecho.", "movimiento": "La MD se mueve formando un arco.", "representacion": "Simula la acción de poner algo debajo de otra cosa.", "definicion": "1. adv. En el lugar o parte inferior. 2. adv. En la parte inferior o interna de algo y cubierto por ello.", "pagina": 2}', ARRAY['Abajo', 'Debajo']::text[], '1. adv. En el lugar o parte inferior. 2. adv. En la parte inferior o interna de algo y cubierto por ello.'),
(5, 'SB', '{"codigo": "B-P 5", "significado": "Abofetear (A)", "tipo_sena": "SB", "configuracion": "MD B-P.2, MB 1.1", "orientacion": "MD la palma inicia hacia afuera y termina hacia adentro, MB palma hacia afuera.", "ubicacion": "MD y MB a la altura del pecho.", "movimiento": "La MD golpea la MB.", "representacion": "Simula la acción de abofetear a alguien.", "definicion": "v. tr. Golpear en la mejilla con la mano abierta.", "pagina": 2}', ARRAY['Abofetear']::text[], 'v. tr. Golpear en la mejilla con la mano abierta.'),
(6, 'SM', '{"codigo": "B-P 6", "significado": "Abofetear (B)", "tipo_sena": "SM", "configuracion": "B-P.2", "orientacion": "La palma inicia hacia la izquierda y termina hacia abajo.", "ubicacion": "A la altura de la mejilla.", "movimiento": "La mano golpea la mejilla.", "rasgos_no_manuales": "Cabeza ladeada.", "representacion": "Simula la acción de abofetear a alguien.", "definicion": "v. tr. Golpear en la mejilla con la mano abierta.", "pagina": 2}', ARRAY['Abofetear']::text[], 'v. tr. Golpear en la mejilla con la mano abierta.'),
(7, 'SB', '{"codigo": "B-P 7", "significado": "Abono", "tipo_sena": "SB", "configuracion": "MD y MB B-P.2", "orientacion": "MD la palma inicia hacia adentro y termina hacia abajo, MB palma hacia arriba con dedo pulgar hacia afuera.", "ubicacion": "A la altura del pecho, MD sobre MB.", "movimiento": "MD recto hacia enfrente repetidamente, rozando a MB con el lateral.", "definicion": "sust. m. Pago parcial, y generalmente periódico, de una deuda. AHORA", "pagina": 3}', ARRAY['Abono']::text[], 'sust. m. Pago parcial, y generalmente periódico, de una deuda. AHORA'),
(8, 'SS', '{"codigo": "B-P 8", "significado": "Abrazar", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Palmas hacia adentro.", "ubicacion": "Sobre el pecho.", "movimiento": "Las manos golpean los hombros repetidamente.", "rasgos_no_manuales": "Se esboza una sonrisa.", "representacion": "Simula la acción de abrazar a alguien.", "definicion": "v. tr. Rodear algo o a dm-ANA alguien con los brazos, sobre todo como muestra de afecto.", "pagina": 3}', ARRAY['Abrazar']::text[], 'v. tr. Rodear algo o a dm-ANA alguien con los brazos, sobre todo como muestra de afecto.'),
(9, 'SS', '{"codigo": "B-P 9", "significado": "Abrir 1 / Abierto, ta 2 (A)", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Las palmas inician hacia adentro y terminan hacia afuera.", "ubicacion": "Del centro del cuello a los hombros.", "movimiento": "Las manos parten de un mismo punto y luego se abren hacia los lados.", "definicion": "1. v. tr. Separar o quitar lo que impide la entrada, la vista, la circulación, etc., entre el interior y el exterior de algo o entre lugares. 2. adj. No cerrado.", "pagina": 3}', ARRAY['Abrir', 'Abierto']::text[], '1. v. tr. Separar o quitar lo que impide la entrada, la vista, la circulación, etc., entre el interior y el exterior de algo o entre lugares. 2. adj. No cerrado.'),
(10, 'SS', '{"codigo": "B-P 10", "significado": "Abrir mente (mente abierta)", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Las palmas inician hacia adentro y terminan hacia afuera.", "ubicacion": "A Ia altura de la frente.", "movimiento": "Las manos parten de un mismo punto y después se abren hacia enfrente y hacia los lados.", "rasgos_no_manuales": "Cabeza adelantada, ceño ligeramente fruncido.", "definicion": "loc. v. Ampliar el criterio para ayudar a averiguar la naturaleza de las cosas.", "pagina": 4}', ARRAY['Abrir mente']::text[], 'loc. v. Ampliar el criterio para ayudar a averiguar la naturaleza de las cosas.'),
(11, 'SB', '{"codigo": "B-P 11", "significado": "Acceso 1 / Accesibilidad 2", "tipo_sena": "SB", "configuracion": "MD y MB B-P.2", "orientacion": "MD palma hacia la izquierda, MB palma hacia arriba.", "ubicacion": "A la altura del pecho, MD sobre MB.", "movimiento": "MD recto hacia enfrente.", "representacion": "Simula la acción de entrar a un lugar.", "definicion": "1. sust. m. Entrada a un lugar; posibilidad de alcanzar o conseguir algo o de entrar a algún lugar. 2. sust. f. Cualidad o propiedad que caracteriza a alguien o algo, de llegar a él con facilidad o sencillamente.", "pagina": 4}', ARRAY['Acceso', 'Accesibilidad']::text[], '1. sust. m. Entrada a un lugar; posibilidad de alcanzar o conseguir algo o de entrar a algún lugar. 2. sust. f. Cualidad o propiedad que caracteriza a alguien o algo, de llegar a él con facilidad o sencillamente.'),
(12, 'SM', '{"codigo": "B-P 12", "significado": "Accidente", "tipo_sena": "SM", "configuracion": "B-P.8", "orientacion": "Palma hacia abajo.", "ubicacion": "Inicia a la altura del pecho y termina sobre la cintura.", "movimiento": "La mano se mueve formando un arco.", "rasgos_no_manuales": "Ojos apretados, boca abierta mostrando los dientes, cuerpo inclinado hacia la derecha.", "representacion": "Simula la acción de herirse.", "definicion": "sust. m. Acontecimiento inesperado y no intencionado que altera el curso normal de las cosas, provocando generalmente alguna desgracia.", "pagina": 4}', ARRAY['Accidente']::text[], 'sust. m. Acontecimiento inesperado y no intencionado que altera el curso normal de las cosas, provocando generalmente alguna desgracia.'),
(13, 'SM', '{"codigo": "B-P 13", "significado": "Activo, -a", "tipo_sena": "SM", "configuracion": "B-P.2", "orientacion": "Palma hacia adentro.", "ubicacion": "Sobre la frente.", "movimiento": "La mano golpea la frente repetidamente.", "definicion": "adj. Que penetra a su pareja durante la relación sexual.", "nota_cultural": "La seña se usa para la comunidad sorda LGBTTTI.", "pagina": 5}', ARRAY['Activo']::text[], 'adj. Que penetra a su pareja durante la relación sexual.'),
(14, 'SM', '{"codigo": "B-P 14", "significado": "Adolfo López Mateos", "tipo_sena": "SM", "configuracion": "B-P.3", "orientacion": "Palma hacia afuera.", "ubicacion": "A la altura de la cabeza.", "movimiento": "La mano simula dos saltos hacia atrás.", "definicion": "Abogado y político mexicano que se desempeñó como el quincuagésimo tercer presidente de los Estados Unidos Mexicanos, ejerciendo como tal durante el sexenio comprendido entre 1958 y ANTES 1964.", "pagina": 5}', ARRAY['Adolfo López Mateos']::text[], 'Abogado y político mexicano que se desempeñó como el quincuagésimo tercer presidente de los Estados Unidos Mexicanos, ejerciendo como tal durante el sexenio comprendido entre 1958 y ANTES 1964.'),
(15, 'SS', '{"codigo": "B-P 15", "significado": "Adorar", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Palmas hacia abajo.", "ubicacion": "Del rostro a la cintura.", "movimiento": "Recto.", "rasgos_no_manuales": "Cabeza agachada.", "definicion": "v. tr. Reverenciar o rendir culto a un ser que se considera de naturaleza divina.", "nota_cultural": "La seña se usa en la comunidad sorda de los Testigos de Jehová.", "pagina": 5}', ARRAY['Adorar']::text[], 'v. tr. Reverenciar o rendir culto a un ser que se considera de naturaleza divina.'),
(16, 'SS', '{"codigo": "B-P 16", "significado": "Aeropuerto", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Palmas hacia afuera.", "ubicacion": "De los hombros a la cabeza, del centro a los lados.", "movimiento": "Recto.", "definicion": "sust. m. Área destinada al aterrizaje y despegue de aviones dotada de instalaciones para el control del tráfico aéreo y de servicios a los pasajeros.", "pagina": 6}', ARRAY['Aeropuerto']::text[], 'sust. m. Área destinada al aterrizaje y despegue de aviones dotada de instalaciones para el control del tráfico aéreo y de servicios a los pasajeros.'),
(17, 'SS', '{"codigo": "B-P 17", "significado": "Afuera 1 / Al aire libre 2", "tipo_sena": "SS", "configuracion": "Seña que pasa de B-P.2 a B-P.8 y a B-P.2", "orientacion": "Las palmas inician hacia afuera y terminan hacia adentro.", "ubicacion": "A la altura del rostro.", "movimiento": "Las muñecas giran y cambian la orientación de las manos, pasan de mostrar las palmas a mostrar el dorso y después recto hacia enfrente.", "definicion": "1. adv. En lugar público o en la parte exterior. 2. loc. adv. En un lugar que se encuentra en el exterior, puede ser de propiedad pública o privada.", "pagina": 6}', ARRAY['Afuera', 'Al aire libre']::text[], '1. adv. En lugar público o en la parte exterior. 2. loc. adv. En un lugar que se encuentra en el exterior, puede ser de propiedad pública o privada.'),
(18, 'SC', '{"codigo": "B-P 18", "significado": "Agenda (B)", "tipo_sena": "SC: I. SS; II. SB; III. SS", "configuracion": "I. B-P. 2; II. MD O.4, MB B-P.2; III. 5.1", "orientacion": "I. Inicia con palmas encontradas frente a frente y termina con palmas hacia arriba; II. MD palma hacia abajo, MB palma hacia arriba; III. Las palmas se encuentran frente a frente.", "ubicacion": "I., II. y III. A la altura del pecho.", "movimiento": "I. Las manos parten de un mismo punto y luego se abren hacia los lados; II. Los dedos de MD golpean a la MB en línea recta; III. Las manos se encuentran frente a frente y se tocan.", "definicion": "sust. f. Libro, cuaderno o dispositivo electrónico en el que se apunta, para no olvidarlo, aquello que se ha de hacer.", "pagina": 6}', ARRAY['Agenda']::text[], 'sust. f. Libro, cuaderno o dispositivo electrónico en el que se apunta, para no olvidarlo, aquello que se ha de hacer.'),
(19, 'SS', '{"codigo": "B-P 19", "significado": "Ah, ya veo –Oh, ya entiendo", "tipo_sena": "SS", "configuracion": "Seña que pasa de B-P.7 a A.1", "orientacion": "Las palmas inician hacia adentro y terminan hacia arriba.", "ubicacion": "Sobre el pecho.", "movimiento": "Recto hacia enfrente mientras los antebrazos giran y los dedos se flexionan.", "rasgos_no_manuales": "Cabeceo de atrás hacia adelante, boca abierta con labios redondeados.", "definicion": "loc. v. Expresión que se OH-YA-ENTIENDO ocupa para afirmar que un asunto o tema ha quedado claro.", "pagina": 7}', ARRAY['Ah, ya veo', 'Oh, ya entiendo']::text[], 'loc. v. Expresión que se OH-YA-ENTIENDO ocupa para afirmar que un asunto o tema ha quedado claro.'),
(20, 'SS', '{"codigo": "B-P 20", "significado": "Ahora 1 / Presente 2 (A)", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Las palmas inician hacia arriba y terminan hacia arriba.", "ubicacion": "A la altura del pecho.", "movimiento": "Las manos parten de un mismo punto y luego se abren hacia los lados.", "definicion": "1. adv. En este momento o en el tiempo actual. 2. sust. m. Época o momento actual que se vive ahora. AHORA", "pagina": 7}', ARRAY['Ahora', 'Presente']::text[], '1. adv. En este momento o en el tiempo actual. 2. sust. m. Época o momento actual que se vive ahora. AHORA'),
(21, 'SB', '{"codigo": "B-P 21", "significado": "Ahora (B)", "tipo_sena": "SB", "configuracion": "MD y MB B-P.2", "orientacion": "MD y MB palmas hacia arriba.", "ubicacion": "MD inicia sobre MB y termina a la altura de la cadera, MB a la altura del pecho.", "movimiento": "MD recto mientras choca contra los dedos de MB repetidamente.", "definicion": "adv. En este momento o en el tiempo actual.", "pagina": 7}', ARRAY['Ahora']::text[], 'adv. En este momento o en el tiempo actual.'),
(22, 'SS', '{"codigo": "B-P 22", "significado": "Alabar 1 / Alabanza 2", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Las palmas se encuentran frente a frente.", "ubicacion": "A la altura del rostro.", "movimiento": "Las manos simulan pequeños aplausos mientras se mueven formando un arco de izquierda a derecha.", "definicion": "1. v. tr. Manifestar el aprecio o la admiración por algo o por alguien, poniendo de relieve sus cualidades o méritos. 2. sust. f. Expresión o conjunto de expresiones con que se alaba.", "nota_cultural": "La seña se usa en la comunidad sorda Amistad Cristiana e Iglesia de Cristo.", "pagina": 8}', ARRAY['Alabar', 'Alabanza']::text[], '1. v. tr. Manifestar el aprecio o la admiración por algo o por alguien, poniendo de relieve sus cualidades o méritos. 2. sust. f. Expresión o conjunto de expresiones con que se alaba.'),
(23, 'SS', '{"codigo": "B-P 23", "significado": "Alegría 1 / Disfrutar 2 / Celebrar 3 / Divertido, da 4", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Palmas hacia adentro.", "ubicacion": "Sobre el pecho.", "movimiento": "De atrás hacia adelante flexionando sólo las muñecas alternadamente.", "rasgos_no_manuales": "Se esboza una sonrisa.", "definicion": "1. sust. f. Sentimiento grato y vivo que suele manifestarse con signos exteriores. 2. v. tr. Percibir o gozar los productos y utilidades de algo. 3. v. tr. Ensalzar públicamente a un ser sagrado o un hecho solemne, religioso o profano, dedicando uno o más días a su recuerdo. 4. adj. Que produce alegría y distracción.", "pagina": 8}', ARRAY['Alegría', 'Disfrutar', 'Celebrar', 'Divertido']::text[], '1. sust. f. Sentimiento grato y vivo que suele manifestarse con signos exteriores. 2. v. tr. Percibir o gozar los productos y utilidades de algo. 3. v. tr. Ensalzar públicamente a un ser sagrado o un hecho solemne, religioso o profano, dedicando uno o más días a su recuerdo. 4. adj. Que produce alegría y distracción.'),
(24, 'SM', '{"codigo": "B-P 24", "significado": "Aléjate", "tipo_sena": "SM", "configuracion": "Seña que pasa de B-P.7 a B-P.2", "orientacion": "La palma inicia hacia adentro y termina hacia afuera.", "ubicacion": "A la altura del pecho.", "movimiento": "Recto hacia enfrente.", "definicion": "v. tr. (uso imperativo) Distanciar, llevar a alguien o algo lejos o más lejos.", "pagina": 8}', ARRAY['Aléjate']::text[], 'v. tr. (uso imperativo) Distanciar, llevar a alguien o algo lejos o más lejos.'),
(25, 'SC', '{"codigo": "B-P 25", "significado": "Aleluya", "tipo_sena": "SC: I. y II. SS", "configuracion": "I. B-P.2; II. Seña que pasa de configuración Q.8 a 5.1", "orientacion": "I. Las palmas se encuentran frente a frente; II. Palmas hacia el centro.", "ubicacion": "I. A la altura del pecho; II. A la altura de los hombros.", "movimiento": "I. Las manos se encuentran y se tocan frente a frente; II. Las manos se mueven formando círculos y después los dedos se extienden.", "definicion": "interj. Demostración de júbilo de la iglesia cristiana, especialmente en tiempo de Pascua.", "nota_cultural": "La seña se usa en la comunidad sorda Amistad Cristiana e Iglesia de Cristo.", "pagina": 9}', ARRAY['Aleluya']::text[], 'interj. Demostración de júbilo de la iglesia cristiana, especialmente en tiempo de Pascua.'),
(26, 'SM', '{"codigo": "B-P 26", "significado": "Alemania 1 (LSM) / Miguel Alemán Valdés 2", "tipo_sena": "SM", "configuracion": "Seña que pasa de B-P.2 a A.1", "orientacion": "Palma hacia adentro.", "ubicacion": "A la altura del cuello, del centro a la derecha.", "movimiento": "Recto.", "definicion": "1. País ubicado en el centro de Europa cuya capital es Berlín. 2. Político y abogado mexicano que se desempeñó como presidente de México del 1 de diciembre de 1946 al 30 de dm-JUAN noviembre de 1952.", "pagina": 9}', ARRAY['Alemania', 'Miguel Alemán Valdés']::text[], '1. País ubicado en el centro de Europa cuya capital es Berlín. 2. Político y abogado mexicano que se desempeñó como presidente de México del 1 de diciembre de 1946 al 30 de dm-JUAN noviembre de 1952.'),
(27, 'SS', '{"codigo": "B-P 27", "significado": "Almeja", "tipo_sena": "SS", "configuracion": "B-P.12", "orientacion": "Las palmas se encuentran frente a frente.", "ubicacion": "A la altura del pecho.", "movimiento": "Las manos parten de un mismo punto y luego se abren hacia arriba y hacia abajo sin separar las muñecas.", "representacion": "Simula el abrir de una almeja.", "definicion": "sust. f. Animal marino dm-SARA comestible, que tiene dos conchas y vive en aguas poco profundas.", "pagina": 9}', ARRAY['Almeja']::text[], 'sust. f. Animal marino dm-SARA comestible, que tiene dos conchas y vive en aguas poco profundas.'),
(28, 'SM', '{"codigo": "B-P 28", "significado": "Alto", "tipo_sena": "SM", "configuracion": "B-P.2", "orientacion": "Palma hacia afuera.", "ubicacion": "A la altura del pecho.", "movimiento": "Recto hacia enfrente.", "definicion": "sust. m. Interrupción o detención de algo.", "pagina": 10}', ARRAY['Alto']::text[], 'sust. m. Interrupción o detención de algo.'),
(29, 'SM', '{"codigo": "B-P 29", "significado": "Amable (B)", "tipo_sena": "SM", "configuracion": "Seña que pasa de B-P.2 a B-P.8", "orientacion": "Palma hacia adentro.", "ubicacion": "A la altura del rostro, del lado derecho.", "movimiento": "El pulgar se mantiene inmóvil mientras los otros cuatro dedos se aproximan hacia la palma repetidamente.", "rasgos_no_manuales": "Cabeza ladeada hacia la izquierda, se esboza una ligera sonrisa.", "definicion": "adj. Que es agradable y cordial; que gusta y se disfruta.", "pagina": 10}', ARRAY['Amable']::text[], 'adj. Que es agradable y cordial; que gusta y se disfruta.'),
(30, 'SB', '{"codigo": "B-P 30", "significado": "Amanecer", "tipo_sena": "SB", "configuracion": "MD y MB B-P.8", "orientacion": "MD y MB palmas hacia adentro.", "ubicacion": "MD del pecho al rostro, MB a la altura del pecho.", "movimiento": "MD recto deslizándose por atrás de MB.", "representacion": "Simula el sol saliendo por el horizonte.", "definicion": "1. v. intr. Aparecer en el horizonte la luz del Sol; comenzar el día. 2. sust. m. Momento en que comienza el día, cuando aparece la luz del sol en el horizonte.", "pagina": 10}', ARRAY['Amanecer']::text[], '1. v. intr. Aparecer en el horizonte la luz del Sol; comenzar el día. 2. sust. m. Momento en que comienza el día, cuando aparece la luz del sol en el horizonte.'),
(31, 'SB', '{"codigo": "B-P 31", "significado": "Ambulancia", "tipo_sena": "SB", "configuracion": "MD B-P.2, MB 1.1", "orientacion": "MD palma hacia adentro, MB palma hacia la derecha.", "ubicacion": "MD a la altura del hombro, del lado izquierdo al derecho, MB sobre el dorso de MD.", "movimiento": "MD ondulante.", "definicion": "sust. f. Vehículo para transportar enfermos o heridos, equipado con lo necesario para auxiliarlos durante el trayecto al hospital o al lugar donde serán atendidos. pos-MI", "pagina": 11}', ARRAY['Ambulancia']::text[], 'sust. f. Vehículo para transportar enfermos o heridos, equipado con lo necesario para auxiliarlos durante el trayecto al hospital o al lugar donde serán atendidos. pos-MI'),
(32, 'SB', '{"codigo": "B-P 32", "significado": "América (SSI)", "tipo_sena": "SB", "configuracion": "MD y MB B-P.2", "orientacion": "MD palma hacia afuera. MB palma hacia adentro.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "No hay movimiento.", "representacion": "Simula la forma del continente americano.", "definicion": "Continente situado entre los océanos Pacífico y Atlántico.", "pagina": 11}', ARRAY['América']::text[], 'Continente situado entre los océanos Pacífico y Atlántico.'),
(33, 'SS', '{"codigo": "B-P 33", "significado": "Andar – Caminar", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Palmas hacia adentro.", "ubicacion": "A la altura del pecho.", "movimiento": "Las manos se mueven alternadamente hacia arriba y hacia abajo mientras los antebrazos giran y cambian la orientación de las manos.", "representacion": "Simula la acción de caminar.", "definicion": "v. intr. Ir de un lugar a otro dando pasos.", "pagina": 11}', ARRAY['Andar', 'Caminar']::text[], 'v. intr. Ir de un lugar a otro dando pasos.'),
