(136, 'SB', '{"codigo": "B-P 136", "significado": "Cortejar", "tipo_sena": "SB", "configuracion": "MD seña que pasa de B-P.2 a B-P.7, MB S.1", "orientacion": "MD palma hacia abajo. MB palma hacia la izquierda.", "ubicacion": "MD sobre los nudillos de MB y se desliza hacia su muñeca. MB a la altura del pecho.", "movimiento": "Recto repetidamente.", "definicion": "v. tr. Tratar una persona de que otra se enamore de ella, diciéndole piropos, actuando con mucha cortesía y consideración hacia ella y cuidando la propia apariencia.", "pagina": 46}', ARRAY['Cortejar']::text[], 'v. tr. Tratar una persona de que otra se enamore de ella, diciéndole piropos, actuando con mucha cortesía y consideración hacia ella y cuidando la propia apariencia.'),
(137, 'SC', '{"codigo": "B-P 137", "significado": "Crema (cosmético)", "tipo_sena": "SC: I. y II. SB", "configuracion": "I. MD B-P.8, MB C.3; II. MD B-P.2, MB C.3", "orientacion": "I. MD la palma inicia hacia abajo y termina hacia arriba. MB palma hacia la derecha; II. MD palma hacia la izquierda. MB palma hacia la derecha.", "ubicacion": "I. MD y MB a la altura del pecho; II. MD sobre la mejilla. MB a la altura del plexo.", "movimiento": "I. La MD se mueve formando un arco sobre la MD mientras el antebrazo gira y cambia la orientación de la palma; II. La MD se mueve formando círculos sobre la mejilla.", "representacion": "Simula la acción de aplicar crema en la mejilla.", "definicion": "sust.f. Sustancia líquida o sólida, espesa y grasosa, que sirve para suavizar o limpiar la piel o para el tratamiento de pieles curtidas.", "pagina": 46}', ARRAY['Crema']::text[], 'sust.f. Sustancia líquida o sólida, espesa y grasosa, que sirve para suavizar o limpiar la piel o para el tratamiento de pieles curtidas.'),
(138, 'SC', '{"codigo": "B-P 138", "significado": "Crema (lácteo)", "tipo_sena": "SC: I. y II. SB", "configuracion": "I. MD B-P.8, MB C.3; II. MD y MB B-P.2", "orientacion": "I. MD la palma inicia hacia abajo y termina hacia arriba. MB palma hacia la derecha; II. MD palma hacia abajo. MB palma hacia arriba", "ubicacion": "I. MD y MB a la altura del pecho; II. MD inicia sobre el pulgar de MB y se desliza hacia su lateral. MB a la altura del pecho.", "movimiento": "I. La MD se mueve formando un arco sobre la MD mientras el antebrazo gira y cambia la orientación de la palma; II. MD recto hacia la derecha sobre la palma de MB.", "definicion": "sust. f. Parte grasosa y espesa de la leche, con la que se hace la mantequilla y se usa en la preparación de algunos platillos y postres.", "pagina": 46}', ARRAY['Crema']::text[], 'sust. f. Parte grasosa y espesa de la leche, con la que se hace la mantequilla y se usa en la preparación de algunos platillos y postres.'),
(139, 'SM', '{"codigo": "B-P 139", "significado": "Colón 1 / San Cristóbal de Las Casas, Chiapas 2", "tipo_sena": "SM", "configuracion": "Seña que pasa de Cristóbal B.P.2 a C.8", "orientacion": "La palma inicia hacia abajo y termina hacia la izquierda.", "ubicacion": "De la sien a la barbilla.", "movimiento": "Los dedos de MD tocan la frente y después la parte inferior de la palma toca la barbilla.", "definicion": "1. (1451-1506) Navegante de origen genovés que trazó y dio a conocer la primera ruta de ida y vuelta de Europa a América. 2. Ciudad del estado de Chiapas perteneciente a HACE-PASADO los Estados Unidos Mexicanos.", "pagina": 47}', ARRAY['Colón', 'San Cristóbal de Las Casas, Chiapas']::text[], '1. (1451-1506) Navegante de origen genovés que trazó y dio a conocer la primera ruta de ida y vuelta de Europa a América. 2. Ciudad del estado de Chiapas perteneciente a HACE-PASADO los Estados Unidos Mexicanos.'),
(140, 'SC', '{"codigo": "B-P 140", "significado": "Crucero", "tipo_sena": "SC: I. SS; II. SM", "configuracion": "I. B-P.2; II. 2.2", "orientacion": "I. Palmas oblicuas hacia arriba y hacia el centro; II. Palma hacia la izquierda.", "ubicacion": "I. A la altura del pecho; II. A la altura de la sien.", "movimiento": "I. y II. Recto hacia enfrente.", "definicion": "sust. m. Viaje por mar, de recreo, en el que se visitan varios puertos de una región. Barco en el que se efectúa ese viaje.", "pagina": 47}', ARRAY['Crucero']::text[], 'sust. m. Viaje por mar, de recreo, en el que se visitan varios puertos de una región. Barco en el que se efectúa ese viaje.'),
