(148, 'SM', '{"codigo": "B-P 148", "significado": "Despedir 1 - Correr 2 (A)", "tipo_sena": "SM", "configuracion": "B-P.2", "orientacion": "La palma inicia hacia arriba y termina hacia la izquierda.", "ubicacion": "Del hombro al rostro.", "movimiento": "La mano se mueve formando un arco, mientras el antebrazo gira y cambia su orientación.", "definicion": "1. v. tr. Quitar a alguien el empleo 2. v. tr. Sacar a alguien de un lugar o despedirlo de algún trabajo.", "pagina": 50}', ARRAY['Despedir', 'Correr']::text[], '1. v. tr. Quitar a alguien el empleo 2. v. tr. Sacar a alguien de un lugar o despedirlo de algún trabajo.'),
(149, 'SB', '{"codigo": "B-P 149", "significado": "Despedir 1 - Correr 2 (B) - Expulsar", "tipo_sena": "SB", "configuracion": "MD seña que pasa de B-P.9 a B-P.2, MB B-P.2", "orientacion": "MD palma hacia abajo. MB palma hacia arriba.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "MD el pulgar permanece inmóvil mientras los otros cuatro dedos se aproximan a la palma y se extienden repetidamente.", "definicion": "1. v. tr. Quitar a alguien el empleo. 2. v. tr. Sacar a alguien de un lugar o despedirlo de algún trabajo. 3. v. tr. Sacar o correr a alguien de alguna parte prohibiéndole su regreso.", "pagina": 50}', ARRAY['Despedir', 'Correr', 'Expulsar']::text[], '1. v. tr. Quitar a alguien el empleo. 2. v. tr. Sacar a alguien de un lugar o despedirlo de algún trabajo. 3. v. tr. Sacar o correr a alguien de alguna parte prohibiéndole su regreso.'),
(150, 'SB', '{"codigo": "B-P 150", "significado": "Detrás", "tipo_sena": "SB", "configuracion": "MD y MB B-P.7", "orientacion": "MD y MB palmas hacia adentro.", "ubicacion": "MD y MB a la altura del pecho.", "movimiento": "La MD se mueve formando un arco hacia atrás por encima de MB.", "definicion": "adv. En la parte de atrás o posterior de algo, a espaldas de alguien.", "pagina": 50}', ARRAY['Detrás']::text[], 'adv. En la parte de atrás o posterior de algo, a espaldas de alguien.'),
(151, 'SS', '{"codigo": "B-P 151", "significado": "Dieta", "tipo_sena": "SS", "configuracion": "B-P.2", "orientacion": "Palmas inician oblicuas hacia arriba y hacia el centro y terminan oblicuas hacia abajo y hacia el centro.", "ubicacion": "Del pecho a la cadera.", "movimiento": "Las manos se mueven formando un arco hacia los lados.", "definicion": "sust. f. Control o regulación metódica de la cantidad y el tipo de alimentos que ingiere un ser vivo; plan alimenticio que sigue alguien, generalmente por motivos de salud y bajo la vigilancia de un médico.", "pagina": 51}', ARRAY['Dieta']::text[], 'sust. f. Control o regulación metódica de la cantidad y el tipo de alimentos que ingiere un ser vivo; plan alimenticio que sigue alguien, generalmente por motivos de salud y bajo la vigilancia de un médico.'),
(152, 'SM', '{"codigo": "B-P 152", "significado": "Distraído, da 1 / Distraer 2", "tipo_sena": "SM", "configuracion": "B-P.2", "orientacion": "Palma hacia abajo.", "ubicacion": "A la altura del cuello.", "movimiento": "La mano se mueve de arriba hacia abajo repetidamente flexionando sólo la muñeca.", "definicion": "1. adj. Que se distrae con facilidad, que generalmente no se da cuenta de lo que sucede a su alrededor, de lo que hace o de lo que dice. 2. v. tr. Hacer que una persona o un animal quite o aparte su atención de aquello en la que la tiene puesta.", "pagina": 51}', ARRAY['Distraído', 'Distraer']::text[], '1. adj. Que se distrae con facilidad, que generalmente no se da cuenta de lo que sucede a su alrededor, de lo que hace o de lo que dice. 2. v. tr. Hacer que una persona o un animal quite o aparte su atención de aquello en la que la tiene puesta.'),
(153, 'SB', '{"codigo": "B-P 153", "significado": "Doblar", "tipo_sena": "SB", "configuracion": "MD y MB B-P.2", "orientacion": "MD y MB las palmas inician hacia arriba y terminan hacia abajo.", "ubicacion": "MD a la altura de la cintura, del lado derecho al centro. MB a la altura de la cintura del lado izquierdo al centro.", "movimiento": "La MD y la MB se mueven formando un arco alternadamente.", "definicion": "v. tr. Poner en contacto una o más partes con el resto de una misma cosa, como tela, un papel u otro material flexible.", "pagina": 51}', ARRAY['Doblar']::text[], 'v. tr. Poner en contacto una o más partes con el resto de una misma cosa, como tela, un papel u otro material flexible.'),
(154, 'SM', '{"codigo": "B-P 154", "significado": "Doble cara – Hipócrita", "tipo_sena": "SM", "configuracion": "B-P.2", "orientacion": "La palma inicia hacia adentro y termina hacia afuera.", "ubicacion": "De la barbilla a la nuca.", "movimiento": "La mano se mueve formando un arco.", "definicion": "adj. Persona que aparenta o finge virtudes y rectitud o que disfraza o esconde sus verdaderos sentimientos o creencias.", "pagina": 52}', ARRAY['Doble cara', 'Hipócrita']::text[], 'adj. Persona que aparenta o finge virtudes y rectitud o que disfraza o esconde sus verdaderos sentimientos o creencias.'),
(155, 'SM', '{"codigo": "B-P 155", "significado": "Droga 1 / Narcotraficante 2", "tipo_sena": "SM", "configuracion": "Seña que pasa de B-P.2 a B-P.16", "orientacion": "Palma oblicua hacia la izquierda y hacia afuera.", "ubicacion": "A la altura del pecho.", "movimiento": "El dedo pulgar se flexiona repetidamnte.", "definicion": "1. sust. f. Sustancia que altera el sistema nervioso y que se consume sin prescripción médica; puede crear adicción y su uso, por lo general, está social o legalmente prohibido o restringido al campo de la medicina. 2. sust. f. y m. Que trafica con estupefacientes.", "pagina": 52}', ARRAY['Droga', 'Narcotraficante']::text[], '1. sust. f. Sustancia que altera el sistema nervioso y que se consume sin prescripción médica; puede crear adicción y su uso, por lo general, está social o legalmente prohibido o restringido al campo de la medicina. 2. sust. f. y m. Que trafica con estupefacientes.'),
(156, 'SC', '{"codigo": "B-P 156", "significado": "Egipcio 1 / Egipto 2 (SSI)", "tipo_sena": "I. y II. SS", "configuracion": "Seña que pasa de B-P.2 a A.5", "orientacion": "Palmas oblicuas hacia abajo y hacia el centro.", "ubicacion": "A la altura del pecho, los dedos se tocan.", "movimiento": "Las manos parten de un mismo punto y luego se abren hacia abajo mientras los dedos se cierran contra la palma.", "representacion": "Simula la forma de una pirámide.", "definicion": "1. adj. Que pertenece a Egipto o se relaciona con él. 2. País ubicado en el norte de África cuya capital es El Cairo.", "pagina": 52}', ARRAY['Egipcio', 'Egipto']::text[], '1. adj. Que pertenece a Egipto o se relaciona con él. 2. País ubicado en el norte de África cuya capital es El Cairo.'),
