(264, 'SC', '{"codigo": "5-G 21", "significado": "Amante", "tipo_sena": "SC: I. SM; II. SB", "configuracion": "I. 5.1; II. MD 1.4, MB S.1", "orientacion": "I. Palma hacia adentro; II. MD la palma inicia hacia adentro y termina hacia arriba. MB palma oblicua hacia la derecha y hacia abajo.", "ubicacion": "I. Sobre el pecho; II. La MD inicia a la altura del cuello y termina sobre MB. MB a la altura del pecho.", "movimiento": "I. La mano se mueve formando círculos; II. La MD se mueve formando un arco.", "definicion": "adj. Persona que mantiene relaciones sexuales con otra fuera del matrimonio.", "pagina": 88}', ARRAY['Amante']::text[], 'adj. Persona que mantiene relaciones sexuales con otra fuera del matrimonio.'),
