(267, 'SB', '{"codigo": "5-G 24", "significado": "Animal", "tipo_sena": "SB", "configuracion": "MD seña que pasa de 5.1 a L.1, MB S.1", "orientacion": "MD palma hacia abajo. MB palma hacia la derecha.", "ubicacion": "MD y MB a la altura del abdomen.", "movimiento": "La MD se mueve formando un círculo hacia atrás y después golpea la MB en línea recta.", "definicion": "sust. m. Ser orgánico que vive, siente y se mueve por propio impulso.", "pagina": 89}', ARRAY['Animal']::text[], 'sust. m. Ser orgánico que vive, siente y se mueve por propio impulso.'),
(268, 'SB', '{"codigo": "5-G 25", "significado": "Antena parabólica 1 / Tulancingo, Hidalgo 2", "tipo_sena": "SB", "configuracion": "MD 5.24, MB 1.1", "orientacion": "MD la palma inicia hacia afuera y termina hacia la izquierda, MB palma hacia adentro.", "ubicacion": "A la altura del pecho, índice de MB sobre muñeca de MB.", "movimiento": "El antebrazo de la MD gira y cambia la orientación de la mano, pasa de mostrar la palma a mostrar el lateral.", "representacion": "Simula el movimiento de una antena.", "definicion": "1. sust. f. Dispositivo que sirve para emitir o recibir ondas electromagnéticas. 2. Ciudad y municipio ubicados en el estado de Hidalgo, perteneciente a los Estados Unidos Mexicanos.", "pagina": 90}', ARRAY['Antena parabólica', 'Tulancingo, Hidalgo']::text[], '1. sust. f. Dispositivo que sirve para emitir o recibir ondas electromagnéticas. 2. Ciudad y municipio ubicados en el estado de Hidalgo, perteneciente a los Estados Unidos Mexicanos.'),
