(385, 'SC', '{"codigo": "A-28", "significado": "Alabanza 1 /Alabar 2", "tipo_sena": "SC: I. y II. SS", "configuracion": "I. A.1; II. B-P.2", "orientacion": "I. y II. Palmas hacia adentro.", "ubicacion": "I. Sobre el pecho; II. Del cuello al rostro.", "movimiento": "I. Recto hacia arriba; II. Las manos se mueven formando un arco hacia arriba y hacia enfrente.", "rasgos_no_manuales": "Mirada hacia arriba.", "definicion": "1. sust. f. Veneración y celebración con oraciones. 2. Expresar con palabras admiración por las cualidades o los méritos de algo o de alguien.", "nota_cultural": "La seña se usa en la comunidad sorda católica.", "pagina": 130}', ARRAY['Alabanza', 'Alabar']::text[], '1. sust. f. Veneración y celebración con oraciones. 2. Expresar con palabras admiración por las cualidades o los méritos de algo o de alguien.'),
(386, 'SM', '{"codigo": "A-29", "significado": "Alcohol", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma hacia adentro.", "ubicacion": "Inicia sobre la barbilla y termina a la altura de los hombros.", "movimiento": "Recto.", "definicion": "sust. m. Líquido incoloro, inflamable, capaz de evaporarse sin ser calentado y de disolver un gran número de sustancias. Se obtiene de la destilación de sustancias vegetales como la caña, la remolacha o la uva, o sintéticamente. Se una en la fabricación de antisépticos como conservador y como disolvente.", "pagina": 130}', ARRAY['Alcohol']::text[], 'sust. m. Líquido incoloro, inflamable, capaz de evaporarse sin ser calentado y de disolver un gran número de sustancias. Se obtiene de la destilación de sustancias vegetales como la caña, la remolacha o la uva, o sintéticamente. Se una en la fabricación de antisépticos como conservador y como disolvente.'),
(387, 'SM', '{"codigo": "A-30", "significado": "Alcohólicos Anónimos", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma hacia afuera.", "ubicacion": "A la altura del pecho.", "movimiento": "La mano simula un salto de izquierda a derecha.", "definicion": "Comunidad de carácter internacional dedicada a ayudar a combatir el alcoholismo.", "pagina": 130}', ARRAY['Alcohólicos Anónimos']::text[], 'Comunidad de carácter internacional dedicada a ayudar a combatir el alcoholismo.'),
(388, 'SM', '{"codigo": "A-31", "significado": "Alma (A)", "tipo_sena": "SM", "configuracion": "Seña que pasa de A.1 a L.1", "orientacion": "Palma hacia la izquierda.", "ubicacion": "Inicia sobre el labio inferior y termina a la altura del rostro.", "movimiento": "La mano se mueve formando un arco hacia arriba y hacia enfrente.", "rasgos_no_manuales": "Boca abierta.", "definicion": "sust. f. Parte inmaterial del ser humano a la que se le atribuyen las propiedades específicas de éste como los sentimientos, los valores morales y el pensamiento.", "pagina": 131}', ARRAY['Alma']::text[], 'sust. f. Parte inmaterial del ser humano a la que se le atribuyen las propiedades específicas de éste como los sentimientos, los valores morales y el pensamiento.'),
(389, 'SC', '{"codigo": "A-32", "significado": "Altar", "tipo_sena": "I. y II. SS", "configuracion": "I. y II. A.1", "orientacion": "I. y II. Palmas hacia afuera.", "ubicacion": "I. A la altura de los hombros del centro a los lados; II. De los hombros a la cintura.", "movimiento": "I. y II. Recto.", "representacion": "Simula la forma de un altar.", "definicion": "sust. m. En algunas religiones, piedra, construcción elevada o montículo donde se celebran ritos religiosos como sacrificios, ofrendas, etc. ANTIER", "nota_cultural": "La seña se usa en la comunidad sorda mormona.", "pagina": 131}', ARRAY['Altar']::text[], 'sust. m. En algunas religiones, piedra, construcción elevada o montículo donde se celebran ritos religiosos como sacrificios, ofrendas, etc. ANTIER'),
(390, 'SM', '{"codigo": "A-33", "significado": "Alto, ta", "tipo_sena": "SM", "configuracion": "A.4", "orientacion": "La palma inicia hacia abajo y termina hacia afuera.", "ubicacion": "De la cintura a la cabeza.", "movimiento": "Recto.", "rasgos_no_manuales": "Cabeza ligeramente inclinada hacia la derecha.", "representacion": "Simula la altura de una persona.", "definicion": "adj. Que mide mucho desde su parte inferior a su parte superior.", "pagina": 131}', ARRAY['Alto']::text[], 'adj. Que mide mucho desde su parte inferior a su parte superior.'),
(391, 'SM', '{"codigo": "A-34", "significado": "Alumno, na", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma hacia adentro.", "ubicacion": "A la altura de la boca.", "movimiento": "La mano se mueve formando círculos.", "definicion": "sust. Persona que estudia bajo la orientación de otra generalmente en una escuela.", "nota_cultural": "El género femenino se articula con ALUMNO + MUJER.", "pagina": 132}', ARRAY['Alumno']::text[], 'sust. Persona que estudia bajo la orientación de otra generalmente en una escuela.'),
(392, 'SB', '{"codigo": "A-35", "significado": "Álvaro Obregón (delegación)", "tipo_sena": "SB", "configuracion": "MD seña que pasa de A.1 a O.1, MB S.1", "orientacion": "MD la palma inicia hacia afuera y termina hacia la izquierda. MB palma hacia adentro.", "ubicacion": "MD sobre MB del antebrazo a la muñeca. MB a la altura del abdomen.", "movimiento": "La MD simula un salto.", "representacion": "Simula el brazo amputado del General Álvaro Obregón.", "definicion": "Delegación ubicada al noroeste de la Ciudad de México.", "pagina": 132}', ARRAY['Álvaro Obregón']::text[], 'Delegación ubicada al noroeste de la Ciudad de México.'),
(393, 'SB', '{"codigo": "A-36", "significado": "Amarillo", "tipo_sena": "SB", "configuracion": "MD A.1, MB S.1", "orientacion": "MD palma hacia arriba. MB palma hacia abajo.", "ubicacion": "MD sobre la muñeca de MB. MB a la altura del pecho.", "movimiento": "MD recto de izquierda a derecha repetidamente.", "definicion": "adj. Dicho de un color: Semejante al del oro o al de la yema de huevo y que ocupa el tercer lugar en el espectro luminoso.", "pagina": 132}', ARRAY['Amarillo']::text[], 'adj. Dicho de un color: Semejante al del oro o al de la yema de huevo y que ocupa el tercer lugar en el espectro luminoso.'),
(394, 'SB', '{"codigo": "A-37", "significado": "Ambicioso, sa", "tipo_sena": "SB", "configuracion": "MD y MB A.1", "orientacion": "MD y MB palmas hacia adentro.", "ubicacion": "MD y MB sobre el pecho.", "movimiento": "MD y MB se mueven formando círculos alternadamente.", "definicion": "adj. Que desea desmedidamente riqueza o poder.", "pagina": 133}', ARRAY['Ambicioso']::text[], 'adj. Que desea desmedidamente riqueza o poder.'),
