(397, 'SM', '{"codigo": "A-40", "significado": "Analfabeto, ta", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma hacia afuera.", "ubicacion": "Inicia sobre la barbilla y termina sobre la frente.", "movimiento": "La mano se mueve formando un arco.", "definicion": "adj. Que no sabe leer ni escribir.", "pagina": 134}', ARRAY['Analfabeto']::text[], 'adj. Que no sabe leer ni escribir.'),
(398, 'SM', '{"codigo": "A-41", "significado": "Anciano", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma hacia abajo.", "ubicacion": "A la altura del cuello.", "movimiento": "La mano se mueve formando círculos hacia enfrente.", "definicion": "sust. y adj. Persona representante de la religión de los Testigos de Jehová similar al pastor.", "nota_cultural": "La seña se usa en la comunidad sorda del Testigo de Je hová.", "pagina": 134}', ARRAY['Anciano']::text[], 'sust. y adj. Persona representante de la religión de los Testigos de Jehová similar al pastor.'),
