(400, 'SM', '{"codigo": "A-43", "significado": "Antiguo, gua 1 / Antiguamente 2", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma oblicua hacia enfrente y hacia abajo.", "ubicacion": "A la altura del pecho.", "movimiento": "La mano se mueve formando círculos hacia el frente repetidamente.", "rasgos_no_manuales": "Mejillas infladas.", "definicion": "adj. Que es de hace mucho tiempo, que se conserva desde el pasado o es muy viejo.", "pagina": 135}', ARRAY['Antiguo', 'Antiguamente']::text[], 'adj. Que es de hace mucho tiempo, que se conserva desde el pasado o es muy viejo.'),
