(403, 'SB', '{"codigo": "A-47", "significado": "Apóstol", "tipo_sena": "SB", "configuracion": "MD seña que pasa de A.1 a L.1, MB S.1", "orientacion": "MD palma hacia abajo. MB palma hacia la derecha.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "La MD se mueve formando un arco, del antebrazo a la muñeca de MB, mientras el dedo índice se extiende.", "definicion": "sust. m. Persona que, con esfuerzo y sacrificio, se dedica a luchar por alguna buena causa o a propagar una doctrina en la que cree.", "nota_cultural": "la seña se usa en la comunidad sorda de los Testigos de Jehová.", "pagina": 136}', ARRAY['Apóstol']::text[], 'sust. m. Persona que, con esfuerzo y sacrificio, se dedica a luchar por alguna buena causa o a propagar una doctrina en la que cree.'),
(404, 'SM', '{"codigo": "A-48", "significado": "Apóstoles (A)", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma hacia adentro.", "ubicacion": "A la altura de la frente.", "movimiento": "La mano se mueve formando círculos.", "definicion": "sust. m. Cada uno de los doce discípulos de Jesucristo, escogidos por él para predicar sus enseñanzas más San Pablo y San Bernabé.", "nota_cultural": "La seña se usa en la comunidad sorda católica.", "pagina": 136}', ARRAY['Apóstoles']::text[], 'sust. m. Cada uno de los doce discípulos de Jesucristo, escogidos por él para predicar sus enseñanzas más San Pablo y San Bernabé.'),
