(406, 'SM', '{"codigo": "A-50", "significado": "Aprovechar", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma hacia la izquierda.", "ubicacion": "Del plexo al hombro.", "movimiento": "La mano se mueve formando un arco hacia arriba y hacia atrás.", "definicion": "v. tr. Emplear útilmente algo, hacerlo provechos o o sacarle el máximo rendimiento.", "nota_cultural": "Generalmente se acompaña de la emisión de un clic bilabial o lengua vibratoria dependiendo de su contexto..", "pagina": 137}', ARRAY['Aprovechar']::text[], 'v. tr. Emplear útilmente algo, hacerlo provechos o o sacarle el máximo rendimiento.'),
(407, 'SS', '{"codigo": "A-51", "significado": "Ardilla", "tipo_sena": "SS", "configuracion": "A.5", "orientacion": "Las palmas se encuentran frente a frente.", "ubicacion": "Sobre la boca.", "rasgos_no_manuales": "Cabeza inclinada, boca abierta mostrando los dientes.", "representacion": "Simula a una ardilla comiendo.", "definicion": "sust. f. Roedor de cola LUGAR grande y peluda que vive en los árboles.", "pagina": 137}', ARRAY['Ardilla']::text[], 'sust. f. Roedor de cola LUGAR grande y peluda que vive en los árboles.'),
(408, 'SS', '{"codigo": "A-52", "significado": "Área", "tipo_sena": "SS", "configuracion": "A.1", "orientacion": "Palmas hacia abajo.", "ubicacion": "A la altura del pecho, los pulgares se encuentran frente a frente.", "movimiento": "Las manos forman un círculo de afuera hacia adentro, uniendo, separando y volviendo a unir los pulgares.", "representacion": "Simula el área o circunferencia de un lugar.", "definicion": "sust. f. Espacio limitado de una superficie, en particular terrestre, que se considera como una unidad.", "pagina": 138}', ARRAY['Área']::text[], 'sust. f. Espacio limitado de una superficie, en particular terrestre, que se considera como una unidad.'),
(409, 'SB', '{"codigo": "A-53", "significado": "Argentina (LSM)", "tipo_sena": "SB", "configuracion": "MD A.1, MB S.1", "orientacion": "MD palma hacia afuera. MB palma hacia abajo.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "MD recto hacia el frente repetidamente.", "definicion": "País ubicado al sur de América cuya capital es Buenos Aires.", "pagina": 138}', ARRAY['Argentina']::text[], 'País ubicado al sur de América cuya capital es Buenos Aires.'),
(410, 'SB', '{"codigo": "A-54", "significado": "Arrepentirse", "tipo_sena": "SB", "configuracion": "MD y MB A.4", "orientacion": "MD palma hacia la izquierda. MB palma hacia la derecha.", "ubicacion": "MD a la altura de la barbilla. MB a la altura de la frente.", "movimiento": "MD se mueve formando un arco y golpea la barbilla. MB se mueve formando un arco y golpea la frente.", "definicion": "v. prnl. Sentirse alguien avergonzado, apenado, triste o enojado consigo mismo por haber pensado, hecho o dejado de hacer algo y generalmente, tener el propósito de que no vuelva a ocurrir.", "pagina": 138}', ARRAY['Arrepentirse']::text[], 'v. prnl. Sentirse alguien avergonzado, apenado, triste o enojado consigo mismo por haber pensado, hecho o dejado de hacer algo y generalmente, tener el propósito de que no vuelva a ocurrir.'),
