(412, 'SB', '{"codigo": "A-56", "significado": "Arroz", "tipo_sena": "SB", "configuracion": "MD A.1, MB B-P.2", "orientacion": "MD palma hacia la izquierda. MB palma hacia arriba.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "La muñeca de MD gira y cambia la orientación de la mano repetidamente.", "definicion": "sust. m. Planta anual propia de terrenos muy húmedos cuyo fruto es un grano oval rico en almidón.", "pagina": 139}', ARRAY['Arroz']::text[], 'sust. m. Planta anual propia de terrenos muy húmedos cuyo fruto es un grano oval rico en almidón.'),
(413, 'SS', '{"codigo": "A-57", "significado": "Arte 1 / Artesanía 2", "tipo_sena": "SS", "configuracion": "A.1", "orientacion": "Palmas oblicuas hacia afuera y hacia el centro.", "ubicacion": "Inicia a la altura de la cara y termina a la altura del pecho.", "movimiento": "Las manos siguen una trayectoria ondulada.", "definicion": "1. sust. m. Actividad creativa del ser humano que, con ciertas técnicas, maneja y transforma materiales e ideas en objetos o representaciones capaces de producir sentimientos, emociones o sensaciones relacionadas con la belleza o con el placer estético. 2. sust. f. Trabajo del artesano y cada uno de los géneros o artes que lo HOY componen como la alfarería, el arte Hoy plumaria,la carpintería o la herrería.", "pagina": 139}', ARRAY['Arte', 'Artesanía']::text[], '1. sust. m. Actividad creativa del ser humano que, con ciertas técnicas, maneja y transforma materiales e ideas en objetos o representaciones capaces de producir sentimientos, emociones o sensaciones relacionadas con la belleza o con el placer estético. 2. sust. f. Trabajo del artesano y cada uno de los géneros o artes que lo HOY componen como la alfarería, el arte Hoy plumaria,la carpintería o la herrería.'),
(414, 'SB', '{"codigo": "A-58", "significado": "Artículo (Derecho jurídico)", "tipo_sena": "SB", "configuracion": "MD A.1, MB B-P.2", "orientacion": "MD palma hacia afuera. MB palma hacia la derecha.", "ubicacion": "A la altura del pecho.", "movimiento": "La MD simula un salto hacia abajo sobre la palma de MB tocándola con el pulgar.", "definicion": "sust. m. Cada una de las partes o secciones, más o menos independientes, en que se divide una ley, un código, un reglamento, etc, y que, por lo general, va marcada o numerada.", "pagina": 140}', ARRAY['Artículo']::text[], 'sust. m. Cada una de las partes o secciones, más o menos independientes, en que se divide una ley, un código, un reglamento, etc, y que, por lo general, va marcada o numerada.'),
(415, 'SM', '{"codigo": "A-59", "significado": "Así", "tipo_sena": "SM", "configuracion": "MD seña que pasa de A.1 a S.1 a I.1", "orientacion": "La palma inicia hacia la izquierda y termina hacia afuera.", "ubicacion": "A la altura del pecho.", "movimiento": "La mano y la muñeca se mueven formando un arco de izquierda hacia afuera.", "rasgos_no_manuales": "Rotación de cabeza de izquierda a derecha.", "definicion": "adv. De esta manera, de este modo, como es, como está.", "pagina": 140}', ARRAY['Así']::text[], 'adv. De esta manera, de este modo, como es, como está.'),
