(449, 'SB', '{"codigo": "A-93", "significado": "Chaparro, rra – Talla baja", "tipo_sena": "SB", "configuracion": "MD A.1, MB B-P.2", "orientacion": "MD la palma inicia hacia la izquierda y termina hacia dentro. MB palma hacia arriba.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "El antebrazo de MD gira y cambia la orientación de la mano, pasa de mostrar la palma a mostrar el dorso.", "definicion": "adj. y sust. Que es de baja estatura. pro-YO", "nota_cultural": "Para la comunidad sorda es un adjetivo común no peyorativo.", "pagina": 151}', ARRAY['Chaparro', 'Talla baja']::text[], 'adj. y sust. Que es de baja estatura. pro-YO'),
