(518, 'SC', '{"codigo": "A-162", "significado": "Registro civil 1 / Casados por el civil 2", "tipo_sena": "SC: I. y II. SB", "configuracion": "I. MD A.1, MB B-P.2; II. MD seña que pasa de 5.2 a O.5, MB B-P.2", "orientacion": "I. MD palma hacia abajo. MB palma hacia arriba; II. MD la palma inicia hacia afuera y termina hacia abajo. MB palma hacia arriba.", "ubicacion": "I. y II. A la altura del pecho. MD sobre MB.", "movimiento": "I. El dedo pulgar de MD simula un salto hacia el frente sobre la MB; II. MD la mano se mueve formando un arco hacia el frente.", "definicion": "1. sust. m. registro en que se hacen constar por autoridades competentes los nacimientos, matrimonios, defunciones y demás hechos relativos al estado civil de las personas.2. sust. m. Matrimonio que se contrae según la ley civil, sin intervención de la autoridad religiosa correspondiente.", "pagina": 174}', ARRAY['Registro civil', 'Casados por el civil']::text[], '1. sust. m. registro en que se hacen constar por autoridades competentes los nacimientos, matrimonios, defunciones y demás hechos relativos al estado civil de las personas.2. sust. m. Matrimonio que se contrae según la ley civil, sin intervención de la autoridad religiosa correspondiente.'),
(519, 'SS', '{"codigo": "A-163", "significado": "Relación sexual 1 / Apareamiento 2", "tipo_sena": "SS", "configuracion": "A.1", "orientacion": "Las palmas se encuentran frente a frente.", "ubicacion": "A la altura del pecho.", "movimiento": "Las manos se encuentran y se tocan repetidamente.", "rasgos_no_manuales": "Mejilla derecha inflada.", "definicion": "1. sust. f. Cópula sexual. 2. sust. m Unión de las hembras de los animales con los machos para su reproducción.", "pagina": 175}', ARRAY['Relación sexual', 'Apareamiento']::text[], '1. sust. f. Cópula sexual. 2. sust. m Unión de las hembras de los animales con los machos para su reproducción.'),
(520, 'SM', '{"codigo": "A-164", "significado": "Reprobar", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma hacia la izquierda.", "ubicacion": "Del hombro al pecho.", "movimiento": "Recto.", "definicion": "v. tr. No aprobar un examen escolar por no demostrar que se tienen los conocimientos mínimos necesarios para ello.", "pagina": 175}', ARRAY['Reprobar']::text[], 'v. tr. No aprobar un examen escolar por no demostrar que se tienen los conocimientos mínimos necesarios para ello.'),
(521, 'SM', '{"codigo": "A-165", "significado": "Sacerdote – Padre", "tipo_sena": "SM", "configuracion": "A.1", "orientacion": "Palma oblicua hacia la izquierda y hacia abajo.", "ubicacion": "A la altura de la frente.", "movimiento": "La mano se mueve formando círculos.", "definicion": "sust. m. Hombre dedicado y consagrado a la celebración de ritos y ceremonias religiosas; entre los católicos, el que ha recibido las órdenes que se requieren para oficiar la misa.", "pagina": 175}', ARRAY['Sacerdote', 'Padre']::text[], 'sust. m. Hombre dedicado y consagrado a la celebración de ritos y ceremonias religiosas; entre los católicos, el que ha recibido las órdenes que se requieren para oficiar la misa.'),
(522, 'SM', '{"codigo": "A-166", "significado": "Saludos 1 / Saludar 2", "tipo_sena": "SM", "configuracion": "A.5", "orientacion": "Palma hacia la izquierda.", "ubicacion": "A la altura del pecho.", "movimiento": "La mano se agita.", "definicion": "1. sust. m. Palabra, expresión o gesto con el que se muestra atención a una persona al encontrarse con ella o que se hace llegar a alguien con la misma intención. 2. v. tr. Dirigir un saludo a alguien generalmente mediante fórmulas de cortesía al encontrarse o despedirse.", "pagina": 176}', ARRAY['Saludos', 'Saludar']::text[], '1. sust. m. Palabra, expresión o gesto con el que se muestra atención a una persona al encontrarse con ella o que se hace llegar a alguien con la misma intención. 2. v. tr. Dirigir un saludo a alguien generalmente mediante fórmulas de cortesía al encontrarse o despedirse.'),
(523, 'SM', '{"codigo": "A-167", "significado": "Sed 1 / Sediento, ta 2", "tipo_sena": "SM", "configuracion": "A.2", "orientacion": "Palma hacia la izquierda.", "ubicacion": "Sobre el cuello.", "movimiento": "La mano se mueve formando un arco hacia abajo.", "rasgos_no_manuales": "Punta de la lengua hacia afuera.", "definicion": "1. sust. f. sing. Necesidad o deseo intenso de tomar líquido, especialmente agua. 2. adj. Que sufre sed.", "pagina": 176}', ARRAY['Sed', 'Sediento']::text[], '1. sust. f. sing. Necesidad o deseo intenso de tomar líquido, especialmente agua. 2. adj. Que sufre sed.'),
(524, 'SB', '{"codigo": "A-168", "significado": "Separar – Terminar (relación de novios)", "tipo_sena": "SB", "configuracion": "MD y MB A.1", "orientacion": "MD y MB palmas hacia dentro.", "ubicacion": "MD y MB a la altura del pecho.", "movimiento": "MD y MB recto hacia abajo alternadamente.", "rasgos_no_manuales": "Comisuras de los labios hacia abajo.", "definicion": "v. tr. Alejar a una persona o una cosa de otra cuyo contacto generalmente es dañino, peligroso o inconveniente; poner o ponerse fuera de contacto.", "pagina": 176}', ARRAY['Separar', 'Terminar']::text[], 'v. tr. Alejar a una persona o una cosa de otra cuyo contacto generalmente es dañino, peligroso o inconveniente; poner o ponerse fuera de contacto.'),
