(526, 'SB', '{"codigo": "A-170", "significado": "Sexto 1 / Escuela primaria 2", "tipo_sena": "SB", "configuracion": "MD seña que pasa A.1 a A.7, MB S.1", "orientacion": "MD palma hacia dentro. MB palma hacia abajo.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "La MD golpea a la MB repetidamente mientras el dedo pulgar se retrae.", "definicion": "1. adj. Que sigue al quinto en orden y precede al séptimo. 2. sust. f. Nivel escolar que antecede a la secundaria y sucede al preescolar cuya duración es de seis años.", "pagina": 177}', ARRAY['Sexto', 'Escuela primaria']::text[], '1. adj. Que sigue al quinto en orden y precede al séptimo. 2. sust. f. Nivel escolar que antecede a la secundaria y sucede al preescolar cuya duración es de seis años.'),
(527, 'SC', '{"codigo": "A-171", "significado": "Sudadera (A)", "tipo_sena": "SC: I. SS; II. SB", "configuracion": "I. A.1; II. MD y MB D.1", "orientacion": "I. y II. Palmas hacia el centro.", "ubicacion": "I. De los hombros al pecho; II. MD y MB a la altura del pecho.", "movimiento": "I. Las manos cruzan hacia el centro y llegan a un punto cercano; II. MD y MB se mueven formando círculos hacia el frente alternadamente.", "definicion": "sust. f. Prenda de vestir de algodón muy grueso que cubre el torso; se utiliza especialmente para hacer deporte y sudar.", "pagina": 177}', ARRAY['Sudadera']::text[], 'sust. f. Prenda de vestir de algodón muy grueso que cubre el torso; se utiliza especialmente para hacer deporte y sudar.'),
(528, 'SC', '{"codigo": "A-172", "significado": "Sudadera (B)", "tipo_sena": "SC: I. SS; II. SB; III. SS.", "configuracion": "I. A.4; II. Q.10, Q.9 y III. Q.9", "orientacion": "I. Palmas hacia afuera; II. MD palma hacia la derecha. MB palma hacia adentro; III. Las palmas inician hacia abajo y terminan hacia arriba.", "ubicacion": "I. A la altura de los hombros; II. MD de la cintura al pecho. III. Del cuello a las sienes.", "movimiento": "I. Las manos cruzan hacia el centro y llegan a un punto cercano; II. MD recto; III. Las manos se mueven fromando un arco hacia arriba.", "representacion": "Simula la acción de ponerse una sudadera.", "definicion": "sust. f. Prenda de vestir de algodón muy grueso que cubre el torso; se utiliza especialmente para hacer deporte y sudar.", "pagina": 178}', ARRAY['Sudadera']::text[], 'sust. f. Prenda de vestir de algodón muy grueso que cubre el torso; se utiliza especialmente para hacer deporte y sudar.'),
