(544, 'SB', '{"codigo": "S-8", "significado": "Agachar 1 / Agacharse 2", "tipo_sena": "SB", "configuracion": "MD S.1, MB B-P.6", "orientacion": "MD palma hacia afuera; MB palma hacia abajo.", "ubicacion": "A la altura del pecho.", "movimiento": "La MD se mueve formando un arco por debajo de la MB.", "rasgos_no_manuales": "Cabeza adelantada.", "definicion": "1. v. tr. Inclinar o bajar alguna parte del cuerpo especialmente la cabeza o el tronco. 2. v. prnl. Inclinarse hacia el suelo ya sea flexionando las piernas o doblando la cintura.", "pagina": 183}', ARRAY['Agachar', 'Agacharse']::text[], '1. v. tr. Inclinar o bajar alguna parte del cuerpo especialmente la cabeza o el tronco. 2. v. prnl. Inclinarse hacia el suelo ya sea flexionando las piernas o doblando la cintura.'),
(545, 'SM', '{"codigo": "S-9", "significado": "Ahorcar", "tipo_sena": "SM", "configuracion": "S.1", "orientacion": "Palma hacia afuera.", "ubicacion": "Inicia sobre el cuello y termina a la altura de la cabeza.", "movimiento": "Recto.", "rasgos_no_manuales": "Cabeza inclinada hacia la izquierda, ojos cerrados.", "definicion": "1. v. tr. Colgar a una persona o un animal por el cuello para darle muerte.", "pagina": 183}', ARRAY['Ahorcar']::text[], '1. v. tr. Colgar a una persona o un animal por el cuello para darle muerte.'),
