(579, 'SB', '{"codigo": "S-43", "significado": "Desobedecer 1 / Desobediente 2", "tipo_sena": "SB", "configuracion": "MD S.1, MB C.1 .", "orientacion": "MD y MB palmas hacia dentro.", "ubicacion": "MD y MB a la altura del pecho.", "movimiento": "MB sostiene la muñeca de MD. MD el antebrazo gira y cambia la orientación de la mano, pasa de mostrar el dorso a mostrar la palma.", "rasgos_no_manuales": "Punta de la lengua hacia fuera.", "representacion": "Simula la acción de ignorar a alguien dándole la espalda.", "definicion": "1. v. tr. No hacer lo que ordenan SIEMPRE las leyes o quienes tienen autoridad. 2. adj. Persona qie no obedece órdenes.", "pagina": 195}', ARRAY['Desobedecer', 'Desobediente']::text[], '1. v. tr. No hacer lo que ordenan SIEMPRE las leyes o quienes tienen autoridad. 2. adj. Persona qie no obedece órdenes.'),
(580, 'SB', '{"codigo": "S-44", "significado": "Desodorante", "tipo_sena": "SB", "configuracion": "MD S.1 MB A.5. +++", "orientacion": "MD palma hacia dentro, MB palma hacia abajo.", "ubicacion": "MB con el brazo y antebrazo levantado en escuadra. MD sobre la axila de MB.", "movimiento": "La MD se mueve de adentro hacia fuera flexionando solo la muñeca.", "representacion": "Simula la acción de ponerse desodorante. SIEMPRE", "definicion": "sust. m. y adj. Sustancia que quita los olores desagradables.", "pagina": 195}', ARRAY['Desodorante']::text[], 'sust. m. y adj. Sustancia que quita los olores desagradables.'),
(581, 'SB', '{"codigo": "S-45", "significado": "El Salvador (LSM)", "tipo_sena": "SB", "configuracion": "MD y MB S.1", "orientacion": "MD palma hacia fuera. MB palma hacia abajo.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "MD recto repetidamente de adentro hacia fuera.", "definicion": "País ubicado en América Central cuya capital es San Salvador.", "pagina": 195}', ARRAY['El Salvador']::text[], 'País ubicado en América Central cuya capital es San Salvador.'),
(582, 'SB', '{"codigo": "S-46", "significado": "Engordar", "tipo_sena": "SB", "configuracion": "MD seña que pasa de S.1; MB S.1", "orientacion": "MD palma hacia arriba MB palma hacia abajo.", "ubicacion": "A la altura del pecho. MD sobre el dorso de MB.", "movimiento": "MD recto hacia el hombro moviendo cada uno de los dedos alternadamente.", "rasgos_no_manuales": "Cabeza ladeada hacia la izquierda y acción de reír.", "definicion": "v. intr. Ponerse gordo, aumentar de peso.", "pagina": 196}', ARRAY['Engordar']::text[], 'v. intr. Ponerse gordo, aumentar de peso.'),
(583, 'SC', '{"codigo": "S-47", "significado": "Envejecer", "tipo_sena": "SC: I. SM; II. SS", "configuracion": "I. S.1; II. Seña que pasa de 4.5 a 4.6", "orientacion": "Iy II. Palmas hacia dentro.", "ubicacion": "I. A la altura de la barbilla; II. De la frente a la barbilla.", "movimiento": "I. La mano se mueve formando un círculo; II. Recto.", "rasgos_no_manuales": "Ceño fruncido, boca abierta mostrando los dientes.", "definicion": "v. intr. Hacerse viejo o anciano; perder la juventud, la fuerza o la salud con la edad.", "pagina": 196}', ARRAY['Envejecer']::text[], 'v. intr. Hacerse viejo o anciano; perder la juventud, la fuerza o la salud con la edad.'),
(584, 'SS', '{"codigo": "S-48", "significado": "Escoba 1 / Barrer 2", "tipo_sena": "SS", "configuracion": "S.1", "orientacion": "Palmas hacia dentro.", "ubicacion": "A la altura del pecho una mano arriba de la otra.", "movimiento": "Recto hacia la derecha y hacia abajo repetidamente.", "definicion": "1. sust. f. Utensilio para barrer que consiste en un manojo de varas secas por lo general muy delgadas, o de varitas de plástico rígido atadas y unidas a un palo largo. 2. v. tr. Arrastrar con una escoba o con algo similar la basura, el polvo, etc. para quitarlo del suelo.", "pagina": 196}', ARRAY['Escoba', 'Barrer']::text[], '1. sust. f. Utensilio para barrer que consiste en un manojo de varas secas por lo general muy delgadas, o de varitas de plástico rígido atadas y unidas a un palo largo. 2. v. tr. Arrastrar con una escoba o con algo similar la basura, el polvo, etc. para quitarlo del suelo.'),
(585, 'SC', '{"codigo": "S-49", "significado": "Esquiar", "tipo_sena": "SC: I. y II. SS", "configuracion": "I. S.1; II. 5.1", "orientacion": "I. Las palmas se encuentran frente a frente; II. Palmas hacia fuera.", "ubicacion": "I. A la altura del pecho; II. A la altura de la cabeza.", "movimiento": "I. Las manos y los brazos se mueven formando un arco de adelante hacia atrás; II. Recto hacia abajo mientras cada uno de los dedos se mueve alternadamente.", "representacion": "Simula la acción de esquiar mientras nieva.", "definicion": "v. intr. Deslizarse con esquís sobre la nieve o sobre el agua. DICIEMBRE", "pagina": 197}', ARRAY['Esquiar']::text[], 'v. intr. Deslizarse con esquís sobre la nieve o sobre el agua. DICIEMBRE'),
(586, 'SM', '{"codigo": "S-50", "significado": "Estornudar", "tipo_sena": "SM", "configuracion": "S.1", "orientacion": "Palma hacia dentro.", "ubicacion": "A la altura de la nariz y la boca.", "rasgos_no_manuales": "Cabeza inclinada hacia adelante, ojos cerrados, boca mostrando los dientes.", "representacion": "Simula un estornudo.", "definicion": "v. intr. Echar aire por la nariz y la boca, repentina e incontrolablemente, como efecto de una contracción de los músculos de los órganos respiratorios causada por irritación de la mucosa nasal como cuando se está resfriado.", "pagina": 197}', ARRAY['Estornudar']::text[], 'v. intr. Echar aire por la nariz y la boca, repentina e incontrolablemente, como efecto de una contracción de los músculos de los órganos respiratorios causada por irritación de la mucosa nasal como cuando se está resfriado.'),
(587, 'SS', '{"codigo": "S-51", "significado": "Expresar 1 / Expresión 2", "tipo_sena": "SS", "configuracion": "Seña que pasa de S.1 a 5.1", "orientacion": "Palmas hacia dentro.", "ubicacion": "A la altura del pecho, las manos juntas.", "movimiento": "Las manos parten de un mismo punto y luego se abren hacia los lados mientras los dedos se extienden.", "definicion": "1. v. tr. Hacer que lo que uno siente o piensa llegue a otra persona principalmente mediante el lenguaje o la obra de creación. 2. sust. f. Fación utilizada para mostrar algo o externarlo.", "pagina": 197}', ARRAY['Expresar', 'Expresión']::text[], '1. v. tr. Hacer que lo que uno siente o piensa llegue a otra persona principalmente mediante el lenguaje o la obra de creación. 2. sust. f. Fación utilizada para mostrar algo o externarlo.'),
(588, 'SM', '{"codigo": "S-52", "significado": "Famoso 1 / Fama 2", "tipo_sena": "SM", "configuracion": "S.1", "orientacion": "La palma incia hacia dentro y termina hacia afuera.", "ubicacion": "Del pecho a la altura.", "movimiento": "Recto hacia el frente, el antebrazo gira y cambia la orientación de la mano, pasa de mostrar el dorso a mostrar la palma.", "definicion": "1. adj. Que es conocido por muchas personas, que tiene fama. 2.sust. f. Opinión pública que se forma acerca de una persona, de un grupo o de una institución, por el carácter de sus obras, por su valor, por su aspecto, etc.", "pagina": 198}', ARRAY['Famoso', 'Fama']::text[], '1. adj. Que es conocido por muchas personas, que tiene fama. 2.sust. f. Opinión pública que se forma acerca de una persona, de un grupo o de una institución, por el carácter de sus obras, por su valor, por su aspecto, etc.'),
