(657, 'SM', '{"codigo": "S-122", "significado": "Sur", "tipo_sena": "SM", "configuracion": "S.1", "orientacion": "Palma hacia fuera.", "ubicacion": "De la cabeza al pecho.", "movimiento": "Recto.", "definicion": "1. sust. m. Punto cardinal situado a la espalda de un observador a cuya derecha se localiza el este. 2. sust. m. Región o territorio situado en la parte sur de un país o de un área geográfica pro-NOSOTROS determinada.", "pagina": 221}', ARRAY['Sur']::text[], '1. sust. m. Punto cardinal situado a la espalda de un observador a cuya derecha se localiza el este. 2. sust. m. Región o territorio situado en la parte sur de un país o de un área geográfica pro-NOSOTROS determinada.'),
(658, 'SC', '{"codigo": "S-123", "significado": "Table Dance", "tipo_sena": "SC", "configuracion": "I. MD y MB S.1, II. MD 2.9, MB 1.1", "orientacion": "I. MD y MB palmas hacia adentro; II. MD Palma de adentro hacia abajo.", "ubicacion": "A la altura del pecho. MB sobre MD.", "movimiento": "I. MD y MB se mueven formando círculos hacia la izquierda y hacia adentro simultáneamente, II. MD forma un medio círculo.", "representacion": "Simula la práctica del baile sujetando un tubo.", "definicion": "sust. m. Espectáculo que presenta danzas eróticas, normalmente de mujeres, sobre TABLE-DANCE una mesa o plataforma, la cual está adicionada con un tubo vertical que funciona como base del baile.", "pagina": 221}', ARRAY['Table Dance']::text[], 'sust. m. Espectáculo que presenta danzas eróticas, normalmente de mujeres, sobre TABLE-DANCE una mesa o plataforma, la cual está adicionada con un tubo vertical que funciona como base del baile.'),
(659, 'SM', '{"codigo": "S-124", "significado": "Taiwan (SSI) (B)", "tipo_sena": "SM", "configuracion": "S.1", "orientacion": "Palma hacia abajo.", "ubicacion": "A la altura de la barbilla.", "movimiento": "La mano se mueve hacia arriba y hacia abajo flexionando sólo la muñeca.", "definicion": "Isla ubicada al este de China cuya capital es Taipéi.", "pagina": 222}', ARRAY['Taiwan']::text[], 'Isla ubicada al este de China cuya capital es Taipéi.'),
(660, 'SB', '{"codigo": "S-125", "significado": "Tarjeta de crédito", "tipo_sena": "SB", "configuracion": "MD S.1, MB B-P.2", "orientacion": "MD palma hacia adentro MB palma hacia arriba.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "MD recto de atrás hacia adelante repetidamente.", "definicion": "sust. f. Plástico rectangular que tiene grabado el nombre y el número de cuenta del cliente de un banco o casa comercial, en el que aparece su firma y con el que puede comprar artículos o pagar servicios a crédito.", "pagina": 222}', ARRAY['Tarjeta de crédito']::text[], 'sust. f. Plástico rectangular que tiene grabado el nombre y el número de cuenta del cliente de un banco o casa comercial, en el que aparece su firma y con el que puede comprar artículos o pagar servicios a crédito.'),
(661, 'SM', '{"codigo": "S-126", "significado": "Tenis", "tipo_sena": "SM", "configuracion": "S.1", "orientacion": "Palma hacia afuera.", "ubicacion": "A la altura de los hombros, de derecha a izquierda y de izquierda a derecha.", "movimiento": "El brazo se mueve formando un arco de ida y de vuelta.", "representacion": "Simula la acción de mover una raqueta de Tenis.", "definicion": "sust. m. Juego en el que dos o cuatro jugadores, en una cancha rectangular dividida en dos por una red, golpean con raquetas una pelota, que debe pasar sobre la red y botar en terreno contrario; si el oponente no consigue devolver la pelota con la raqueta a la cancha contraria sin que la pelota haya botado dos veces pierde ese punto.", "pagina": 222}', ARRAY['Tenis']::text[], 'sust. m. Juego en el que dos o cuatro jugadores, en una cancha rectangular dividida en dos por una red, golpean con raquetas una pelota, que debe pasar sobre la red y botar en terreno contrario; si el oponente no consigue devolver la pelota con la raqueta a la cancha contraria sin que la pelota haya botado dos veces pierde ese punto.'),
(662, 'SB', '{"codigo": "S-127", "significado": "Tepito (STC Metro)", "tipo_sena": "SB", "configuracion": "MD S.1, MB C.7", "orientacion": "MD y MB palmas hacia adentro.", "ubicacion": "A la altura del pecho. MB sostiene la muñeca de MD.", "definicion": "Estación del Metro de la Ciudad de México perteneciente a la línea B.", "pagina": 223}', ARRAY['Tepito']::text[], 'Estación del Metro de la Ciudad de México perteneciente a la línea B.'),
