(664, 'SM', '{"codigo": "S-129", "significado": "Tirar", "tipo_sena": "SM", "configuracion": "Seña que pasa de S.1 a 5.1", "orientacion": "La palma inicia hacia afuera y termina hacia abajo.", "ubicacion": "Del hombro a la cintura.", "movimiento": "Recto hacia el frente.", "representacion": "Simula la acción de arrojar algo al piso.", "definicion": "1. v. tr. Hacer caer alguna cosa o a alguna persona empujándola o aventándola. 2. v. tr. Echar algo a la basura o deshacerse de ello.", "pagina": 223}', ARRAY['Tirar']::text[], '1. v. tr. Hacer caer alguna cosa o a alguna persona empujándola o aventándola. 2. v. tr. Echar algo a la basura o deshacerse de ello.'),
