(925, 'SM', '{"codigo": "O-1", "significado": "¡Qué padre! – ¡Qué chido!", "tipo_sena": "SM", "configuracion": "Seña que pasa de O.1 a 5.4", "orientacion": "Palma hacia adentro.", "ubicacion": "La mano inicia sobre la boca y termina a la altura del abdomen.", "movimiento": "La mano se mueve formando el número siete mientras los dedos se extienden simultáneamente.", "rasgos_no_manuales": "Cabeza inclinada, cejas hacia arriba, boca semiabierta.", "representacion": "Simula la acción de lanzar un beso hacia la persona u objeto referido.", "definicion": "loc. adv. Que es muy bueno, muy divertido, de buena calidad, etc.", "pagina": 312}', ARRAY['¡Qué padre!', '¡Qué chido!']::text[], 'loc. adv. Que es muy bueno, muy divertido, de buena calidad, etc.'),
