(931, 'SB', '{"codigo": "O-7", "significado": "Abarrotado, da", "tipo_sena": "SB", "configuracion": "MD O.5, MB S.1", "orientacion": "MD palma hacia abajo. MB palma hacia adentro.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "La MD se mueve formando círculos.", "rasgos_no_manuales": "Cejas hacia arriba, mejillas infladas.", "definicion": "adj. Muy lleno; atiborrado, atestado; colmado.", "pagina": 314}', ARRAY['Abarrotado']::text[], 'adj. Muy lleno; atiborrado, atestado; colmado.'),
