(954, 'SS', '{"codigo": "O-30", "significado": "Difundir", "tipo_sena": "SS", "configuracion": "I O.1 y II 5.1", "orientacion": "Palmas hacia abajo con puntas de los dedos hacia el frente.", "ubicacion": "A la altura del pecho.", "movimiento": "Las manos parten de un mismo punto y luego se abren hacia los lados.", "rasgos_no_manuales": "Cabeza atrás, cejas arriba.", "definicion": "v. tr. Hacer que algo llegue a muchas personas principalmente a su conocimiento.", "pagina": 321}', ARRAY['Difundir']::text[], 'v. tr. Hacer que algo llegue a muchas personas principalmente a su conocimiento.'),
(955, 'SC', '{"codigo": "O-31", "significado": "Dirección", "tipo_sena": "SC: I. y II. SS", "configuracion": "I. O.9; II C.1", "orientacion": "I. Palmas hacia adentro; II. Palmas oblicuas hacia el centro y hacia arriba.", "ubicacion": "I. Las manos inician sobre la cintura y terminan sobre el pecho; II. A la altura del pecho.", "movimiento": "I. Las manos simulan un salto; II. Recto hacia el frente.", "definicion": "sust. f. Localización de una casa, un edificio, etc., en una población; conjunto de las indicacio nes que la señalan.", "pagina": 322}', ARRAY['Dirección']::text[], 'sust. f. Localización de una casa, un edificio, etc., en una población; conjunto de las indicacio nes que la señalan.'),
(956, 'SS', '{"codigo": "O-32", "significado": "Donar", "tipo_sena": "SS", "configuracion": "Seña que pasa de O.5 a 5.2", "orientacion": "Las palmas inician hacia adentro y terminan hacia arriba.", "ubicacion": "De los hombros al pecho.", "movimiento": "Las manos se mueven formando un arco mientras los dedos se extienden.", "rasgos_no_manuales": "Se emite un click.", "representacion": "Simula la acción de brindar algo a alguien.", "definicion": "v. tr. Ceder o dar alguien algo que le pertenece como ayuda o contribución.", "pagina": 322}', ARRAY['Donar']::text[], 'v. tr. Ceder o dar alguien algo que le pertenece como ayuda o contribución.'),
(957, 'SB', '{"codigo": "O-33", "significado": "Dromedario", "tipo_sena": "SB", "configuracion": "MD O.5, MB 5.4", "orientacion": "MD palma hacia afuera. MB palma hacia abajo.", "ubicacion": "A la altura de la barbilla. MD delante de MB.", "movimiento": "La MD se mueve de atrás hacia adelante flexionando solo la muñeca, la MB simula un salto.", "definicion": "sust. m. Mamífero rumiante de cabeza pequeña y alargada y cuello largo. Es alto, corpulento, con una giba o joroba en el lomo formada por acumulación de grasa. Vive en los desiertos de Asia y África donde se utiliza como cabalgadura y para carga.", "pagina": 322}', ARRAY['Dromedario']::text[], 'sust. m. Mamífero rumiante de cabeza pequeña y alargada y cuello largo. Es alto, corpulento, con una giba o joroba en el lomo formada por acumulación de grasa. Vive en los desiertos de Asia y África donde se utiliza como cabalgadura y para carga.'),
(958, 'SS', '{"codigo": "O-34", "significado": "Emoción1 / Emocionar 2", "tipo_sena": "SS", "configuracion": "Seña que pasa de O.5 a 5.4", "orientacion": "Palmas hacia adentro.", "ubicacion": "Del pecho a los hombros.", "movimiento": "Recto mientras los dedos se extienden.", "rasgos_no_manuales": "Cabeza ladeada, boca abierta mostrando los dientes, hombros encogidos.", "representacion": "Simula la sensación de erizar la piel.", "definicion": "1. sust. f. Sentimiento intenso, particularmente de alegría o de expectación que domina el estado de ánimo de una persona. 2. v. tr. o prnl. Producir emoción.", "pagina": 323}', ARRAY['Emoción', 'Emocionar']::text[], '1. sust. f. Sentimiento intenso, particularmente de alegría o de expectación que domina el estado de ánimo de una persona. 2. v. tr. o prnl. Producir emoción.'),
(959, 'SB', '{"codigo": "O-35", "significado": "Emocionado, -a 1 / Emocionar 2", "tipo_sena": "SB", "configuracion": "MD O.1, MB 4.1", "orientacion": "MD y MB palmas hacia abajo.", "ubicacion": "A la altura de la cintura. MD sobre MB, de la muñeca al hombro.", "movimiento": "Cada uno de los dedos se mueve alternadamente.", "rasgos_no_manuales": "Acción de sonreír suavemente.", "representacion": "Simula la sensación de erizar la piel.", "definicion": "1.adj. Que se encuentra bajo los efectos de una emoción. 2. v. tr. Producir emoción.", "pagina": 323}', ARRAY['Emocionado', 'Emocionar']::text[], '1.adj. Que se encuentra bajo los efectos de una emoción. 2. v. tr. Producir emoción.'),
(960, 'SM', '{"codigo": "O-36", "significado": "Flojo, ja1 / Flojera2", "tipo_sena": "SM", "configuracion": "Seña que pasa de O.1 a 5.1", "orientacion": "La palma inicia hacia adentro y termina hacia la izquierda.", "ubicacion": "Sobre la sien.", "movimiento": "Recto hacia abajo mientras los dedos se extienden.", "definicion": "1. adj. y sust. m. Que no trabaja o no le gusta trabajar, que tiene o siente flojera. 2. sust. f. Estado en que se encuentra una persona cuando le falta ánimo para hacer algo, no siente deseos de nada o no quiere trabajar.", "pagina": 323}', ARRAY['Flojo', 'Flojera']::text[], '1. adj. y sust. m. Que no trabaja o no le gusta trabajar, que tiene o siente flojera. 2. sust. f. Estado en que se encuentra una persona cuando le falta ánimo para hacer algo, no siente deseos de nada o no quiere trabajar.'),
(961, 'SB', '{"codigo": "O-37", "significado": "Frijol", "tipo_sena": "SB", "configuracion": "MD O.1, MB Configuración 1", "orientacion": "MD y MB palmas hacia abajo.", "ubicacion": "MD y MB a la altura del pecho, la MD sujeta el dedo índice de la MB.", "movimiento": "La muñeca de MD gira sin cambiar la orientación de la mano.", "definicion": "sust. m. Semilla de una planta leguminosa de aproximadamente 10 mm de largo y de distintos colores. Crece en vainas y es parte fundamental de la dieta de los mexicanos.", "pagina": 324}', ARRAY['Frijol']::text[], 'sust. m. Semilla de una planta leguminosa de aproximadamente 10 mm de largo y de distintos colores. Crece en vainas y es parte fundamental de la dieta de los mexicanos.'),
(962, 'SB', '{"codigo": "O-38", "significado": "Hablador, -a1 / Broma 2", "tipo_sena": "SB", "configuracion": "MD O.9, MB B-P.2", "orientacion": "MD palma hacia abajo. MB palma hacia arriba.", "ubicacion": "La MD inicia sobre la palma de MB y se desliza hacia sus dedos. MB a la altura del pecho.", "movimiento": "MD recto repetidamente.", "rasgos_no_manuales": "Cabeza hacia atrás, mejillas infladas.", "definicion": "1. sust. f. y m. Persona que tiende a decir o afirmar cosas sin fundamento, sin tener certeza de lo que dice, o solamente por aparentar o asombrar. 2. sust. f. Hecho o dicho divertido, humorístico, que se caracteriza por desorientar a una persona respecto del acontecimiento real o de la verdad de algo.", "pagina": 324}', ARRAY['Hablador', 'Broma']::text[], '1. sust. f. y m. Persona que tiende a decir o afirmar cosas sin fundamento, sin tener certeza de lo que dice, o solamente por aparentar o asombrar. 2. sust. f. Hecho o dicho divertido, humorístico, que se caracteriza por desorientar a una persona respecto del acontecimiento real o de la verdad de algo.'),
(963, 'SM', '{"codigo": "O-39", "significado": "Horrible", "tipo_sena": "SM", "configuracion": "O.4", "orientacion": "La palma inicia hacia adentro y termina hacia arriba.", "ubicacion": "La mano inicia sobre la frente y termina a la altura del pecho.", "movimiento": "La mano sigue la trayectoria de la Z.", "rasgos_no_manuales": "Ceño fruncido, labios protuidos.", "definicion": "adj. m. y f. Que provoca horror por su fealdad, su maldad, su crueldad, etc.", "pagina": 324}', ARRAY['Horrible']::text[], 'adj. m. y f. Que provoca horror por su fealdad, su maldad, su crueldad, etc.'),
(964, 'SB', '{"codigo": "O-40", "significado": "Inscribir – Ingresar1 / Inscripción2", "tipo_sena": "SB", "configuracion": "MD que pasa de O.5 a 5.2, MB C.3", "orientacion": "MD palma hacia afuera. MB palma oblicua hacia adentro.", "ubicacion": "MD y MB a la altura del pecho.", "movimiento": "MD golpea la MB y se mueve formando un arco hacia el frente por encima de ésta.", "definicion": "1. v. tr. Entrar a formar parte de una organización o institución. 2. sust. m. Entrada o inicio de actividades de alguien en una organización o institución.", "pagina": 325}', ARRAY['Inscribir', 'Ingresar', 'Inscripción']::text[], '1. v. tr. Entrar a formar parte de una organización o institución. 2. sust. m. Entrada o inicio de actividades de alguien en una organización o institución.'),
(965, 'SB', '{"codigo": "O-41", "significado": "Mancha", "tipo_sena": "SB", "configuracion": "MD y MB seña que pasa de O.5 a 5.2", "orientacion": "MD y MB palmas hacia adentro.", "ubicacion": "MD sobre el pecho, MB sobre el estómago.", "movimiento": "Los dedos se extienden alternamente.", "rasgos_no_manuales": "Lengua hacia afuera.", "definicion": "sust. f. Porción de alguna cosa, como una gota de líquido, un fragmento de comida, etc. que ensucia o echa a perder una cosa por ser de apariencia o color distinto del que domina en ella.", "pagina": 325}', ARRAY['Mancha']::text[], 'sust. f. Porción de alguna cosa, como una gota de líquido, un fragmento de comida, etc. que ensucia o echa a perder una cosa por ser de apariencia o color distinto del que domina en ella.'),
(966, 'SB', '{"codigo": "O-42", "significado": "Microscopio", "tipo_sena": "SB", "configuracion": "MD y MB O.1", "orientacion": "MD palma hacia la izquierda. MB palma hacia la derecha.", "ubicacion": "Sobre el ojo izquierdo. MD debajo de MB.", "movimiento": "Las manos se mueven de atrás hacia adelante flexionando sólo la muñeca.", "rasgos_no_manuales": "Cabeza ladeada hacia la izquierda, ojo izquierdo semicerrado.", "representacion": "Simula la acción de observar a través de dicho objeto.", "definicion": "sust. m. Instrumento óptico que permite ver objetos muy pequeños, incluso algunos no perceptibles a simple vista.", "pagina": 325}', ARRAY['Microscopio']::text[], 'sust. m. Instrumento óptico que permite ver objetos muy pequeños, incluso algunos no perceptibles a simple vista.'),
(967, 'SB', '{"codigo": "O-43", "significado": "Mover", "tipo_sena": "SB", "configuracion": "MD y MB O.5", "orientacion": "MD y MB palmas hacia abajo.", "ubicacion": "MD y MB a la altura del abdomen.", "movimiento": "MD y MB recto hacia el frente alternadamente.", "definicion": "v. tr. Hacer que algo o alguien deje el lugar o la posición en que estaba y pase a otro lugar o VECINO posición.", "pagina": 326}', ARRAY['Mover']::text[], 'v. tr. Hacer que algo o alguien deje el lugar o la posición en que estaba y pase a otro lugar o VECINO posición.'),
(968, 'SS', '{"codigo": "O-44", "significado": "Muchos, chas 1 / Numerosos, sas 2 (A)", "tipo_sena": "SS", "configuracion": "O.5", "orientacion": "Palmas hacia arriba.", "ubicacion": "Del pecho al abdomen.", "movimiento": "Recto repetidamente.", "rasgos_no_manuales": "Boca abierta y mostrando los dientes.", "definicion": "1. adj. y pron. Que es abundante, numeroso o de mayor cantidad que lo normal. 2. adj. Que está formado por un gran número de elementos.", "pagina": 326}', ARRAY['Muchos', 'Numerosos']::text[], '1. adj. y pron. Que es abundante, numeroso o de mayor cantidad que lo normal. 2. adj. Que está formado por un gran número de elementos.'),
(969, 'SM', '{"codigo": "O-45", "significado": "Ni modo 1 / Aunque 2", "tipo_sena": "SM", "configuracion": "O.5", "orientacion": "Palma hacia adentro.", "ubicacion": "La mano inicia sobre la barbilla y termina sobre el pecho.", "movimiento": "La mano simula un salto.", "rasgos_no_manuales": "Boca abierta y mostrando los dientes.", "definicion": "1. loc. adv. Sin remedio, sin otra posibilidad o sin que pueda hacerse otra cosa; expresa también indiferencia por lo sucedido. 2. Expresa una objeción que no impide el desarrollo de la acción principal.", "pagina": 326}', ARRAY['Ni modo', 'Aunque']::text[], '1. loc. adv. Sin remedio, sin otra posibilidad o sin que pueda hacerse otra cosa; expresa también indiferencia por lo sucedido. 2. Expresa una objeción que no impide el desarrollo de la acción principal.'),
(970, 'SM', '{"codigo": "O-46", "significado": "No hacer caso", "tipo_sena": "SM", "configuracion": "O.5", "orientacion": "Palma hacia la izquierda.", "ubicacion": "A la altura de la barbilla.", "movimiento": "Recto hacia la derecha.", "rasgos_no_manuales": "Cabeza ladeada, ceño fruncido, boca abierta mostrando los dientes.", "definicion": "loc. verb. Pasar por alto a propósito o no prestarle atención a una cosa o a una persona.", "pagina": 327}', ARRAY['No hacer caso']::text[], 'loc. verb. Pasar por alto a propósito o no prestarle atención a una cosa o a una persona.'),
(971, 'SS', '{"codigo": "O-47", "significado": "No hay nadie", "tipo_sena": "SS", "configuracion": "O.4", "orientacion": "Palmas oblicuas hacia fuera y hacia los lados.", "ubicacion": "A la altura del pecho, las manos cruzadas.", "movimiento": "Las manos parten de un mismo punto y luego se abren hacia los lados.", "rasgos_no_manuales": "Rotación de cabeza, ojos semicerrados, mejillas infladas.", "definicion": "v. imp. No haber alguien en algún lugar.", "pagina": 327}', ARRAY['No hay nadie']::text[], 'v. imp. No haber alguien en algún lugar.'),
(972, 'SS', '{"codigo": "O-48", "significado": "No te he visto / Hacer mucho que no te veo", "tipo_sena": "SS", "configuracion": "O.1", "orientacion": "Las palmas se encuentran frente a frente.", "ubicacion": "A la altura de las mejillas.", "movimiento": "Recto hacia el frente.", "rasgos_no_manuales": "Ceño fruncido y labios protuidos.", "definicion": "v. tr. No haber visto a alguien en mucho tiempo.", "pagina": 327}', ARRAY['No te he visto', 'Hacer mucho que no te veo']::text[], 'v. tr. No haber visto a alguien en mucho tiempo.'),
(973, 'SB', '{"codigo": "O-49", "significado": "Nuevo, va", "tipo_sena": "SB", "configuracion": "MD seña que pasa de O.5 a 5.1, MB C.3", "orientacion": "MD y MB palmas hacia adentro.", "ubicacion": "MD del pecho a la cabeza. MB a la altura del pecho del lado derecho.", "movimiento": "MD recto.", "definicion": "adj. Que tiene poco tiempo o acaba de ser hecho o fabricado.", "pagina": 328}', ARRAY['Nuevo']::text[], 'adj. Que tiene poco tiempo o acaba de ser hecho o fabricado.'),
