(975, 'SM', '{"codigo": "O-51", "significado": "Oaxaca, Oaxaca", "tipo_sena": "SM", "configuracion": "O.1", "orientacion": "La palma inicia hacia adentro y termina hacia afuera.", "ubicacion": "A la altura de la cara.", "movimiento": "El antebrazo gira y cambia la orientación de la mano, pasa de mostrar el dorso a mostrar la palma.", "definicion": "Capital del estado Oaxaca pertenciente a los Estados Unidos Mexicanos.", "pagina": 328}', ARRAY['Oaxaca, Oaxaca']::text[], 'Capital del estado Oaxaca pertenciente a los Estados Unidos Mexicanos.'),
