(980, 'SB', '{"codigo": "O-56", "significado": "Obra teatral", "tipo_sena": "SB", "configuracion": "Seña que pasa de O.1 a Configuración F", "orientacion": "Palmas hacia abajo.", "ubicacion": "A la altura del pecho.", "movimiento": "Los dedos medio, anular y meñique se extienden.", "definicion": "sust. f. Lugar de trabajo en el que se realizan actividades administrativas y de atención al público, o donde se ofrece algún servicio profesional. JEFE", "pagina": 330}', ARRAY['Obra teatral']::text[], 'sust. f. Lugar de trabajo en el que se realizan actividades administrativas y de atención al público, o donde se ofrece algún servicio profesional. JEFE'),
(981, 'SM', '{"codigo": "O-58", "significado": "Oración1 / Orar 2", "tipo_sena": "SM", "configuracion": "O.1", "orientacion": "Palma hacia adentro.", "ubicacion": "Frente a la boca.", "movimiento": "La mano se mueve de arriba hacia abajo flexionando sólo la muñeca.", "definicion": "1. sust. f. Invocación religiosa para dirigirse a un ser divino especialmente a Dios o a los santos para rendir culto o para pedir o agradecer algo. 2. v. intr. Dirigir oraciones a Dios, a otra divinidad o a algún santo; rezar.", "pagina": 331}', ARRAY['Oración', 'Orar']::text[], '1. sust. f. Invocación religiosa para dirigirse a un ser divino especialmente a Dios o a los santos para rendir culto o para pedir o agradecer algo. 2. v. intr. Dirigir oraciones a Dios, a otra divinidad o a algún santo; rezar.'),
(982, 'SM', '{"codigo": "O-59", "significado": "Orden 1 / Oración2 / Organizar3 (A)", "tipo_sena": "SM", "configuracion": "O.1", "orientacion": "Palma hacia adentro.", "ubicacion": "A la altura del pecho.", "movimiento": "Recto, de izquierda a derecha.", "definicion": "1. sust. m. Manera en que se ponen o se arreglan varios elementos de acuerdo con el lugar que les corresponde o con un criterio determinado, y criterio o regla con el que se disponen. 2. sust. f. Estructura gramatical formada por la unión de un sujeto y un predicado. 3. v. tr. Establecer o modificar algo para que funcione ordenada y efectivamente.", "pagina": 331}', ARRAY['Orden', 'Oración', 'Organizar']::text[], '1. sust. m. Manera en que se ponen o se arreglan varios elementos de acuerdo con el lugar que les corresponde o con un criterio determinado, y criterio o regla con el que se disponen. 2. sust. f. Estructura gramatical formada por la unión de un sujeto y un predicado. 3. v. tr. Establecer o modificar algo para que funcione ordenada y efectivamente.'),
(983, 'SB', '{"codigo": "O-60", "significado": "Orizaba, Veracruz", "tipo_sena": "SB", "configuracion": "MD O.1, MB B-P.2", "orientacion": "MD palma inicia hacia la derecha y termina hacia la izquierda. MB palma hacia arriba.", "ubicacion": "MD sobre MB. MB a la altura del pecho.", "movimiento": "El antebrazo de MD gira y cambia la orientación de la mano.", "definicion": "Ciudad del estado de Veracruz, perteneciente a los Estados Unidos Mexicanos.", "pagina": 331}', ARRAY['Orizaba, Veracruz']::text[], 'Ciudad del estado de Veracruz, perteneciente a los Estados Unidos Mexicanos.'),
(984, 'SM', '{"codigo": "O-61", "significado": "Oro (A)", "tipo_sena": "SM", "configuracion": "Seña que pasa de O.1 a Configuración R a O.1", "orientacion": "Palma hacia el frente.", "ubicacion": "A la altura del hombro.", "definicion": "sust. m. Metal precioso de color amarillo brillante al que pueden dársele distintas formas. Es muy pesado, inalterable e inoxidable y se encuentra en la naturaleza no combinado con otros metales.", "pagina": 332}', ARRAY['Oro']::text[], 'sust. m. Metal precioso de color amarillo brillante al que pueden dársele distintas formas. Es muy pesado, inalterable e inoxidable y se encuentra en la naturaleza no combinado con otros metales.'),
(985, 'SB', '{"codigo": "O-62", "significado": "Oro (B)", "tipo_sena": "SB", "configuracion": "MD O.1, MB B-P. 2", "orientacion": "MD palma hacia la izquierda. MB palma hacia arriba.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "La MD golpea a la MB en línea recta repetidamente.", "definicion": "sust. m. Metal precioso de color amarillo brillante al que pueden dársele distintas formas. MARATÓN", "pagina": 332}', ARRAY['Oro']::text[], 'sust. m. Metal precioso de color amarillo brillante al que pueden dársele distintas formas. MARATÓN'),
(986, 'SS', '{"codigo": "O-63", "significado": "Oscuro, -a 1 / Oscuridad 2", "tipo_sena": "SS", "configuracion": "O.1", "orientacion": "Palmas hacia el centro.", "ubicacion": "A la altura de la cara.", "movimiento": "Las manos cruzan hacia el centro y llegan a un punto cercano.", "rasgos_no_manuales": "Ceño fruncido, ojos apretados, labios protuidos.", "definicion": "1. adj. Que carece de luz o que recibe muy poca luz. 2. sust. f. Ausencia o falta de luz.", "pagina": 332}', ARRAY['Oscuro', 'Oscuridad']::text[], '1. adj. Que carece de luz o que recibe muy poca luz. 2. sust. f. Ausencia o falta de luz.'),
(987, 'SS', '{"codigo": "O-64", "significado": "Ovarios", "tipo_sena": "SS", "configuracion": "O.1", "orientacion": "Las palmas se encuentran frente a frente.", "ubicacion": "Sobre la cadera.", "movimiento": "Las manos golpean la cadera repetidamente.", "definicion": "sust. m. Glándulas reproductoras femeninas situadas a uno y otro lado del útero; en ellas se producen los óvulos.", "pagina": 333}', ARRAY['Ovarios']::text[], 'sust. m. Glándulas reproductoras femeninas situadas a uno y otro lado del útero; en ellas se producen los óvulos.'),
(988, 'SS', '{"codigo": "O-65", "significado": "Oxxo ®", "tipo_sena": "SS", "configuracion": "O.1", "orientacion": "Palmas oblicuas hacia abajo y hacia los lados.", "ubicacion": "A la altura del cuello.", "movimiento": "Las muñecas se encuentran y se tocan repetidamente.", "representacion": "La seña representa el logotipo de la tienda de conveniencia en cuestión.", "definicion": "Cadena mexicana de tiendas de conveniencia propiedad de FEMSA. Éstas se caracterizan por vender abarrotes y ofrecer el pago de servicios a los clientes.", "pagina": 333}', ARRAY['Oxxo ®']::text[], 'Cadena mexicana de tiendas de conveniencia propiedad de FEMSA. Éstas se caracterizan por vender abarrotes y ofrecer el pago de servicios a los clientes.'),
(989, 'SS', '{"codigo": "O-66", "significado": "Perder", "tipo_sena": "SS", "configuracion": "Seña que pasa de O.1 a 5.2", "orientacion": "Las palmas inician encontrándose frente a frente y terminan hacia abajo.", "ubicacion": "A la altura del pecho.", "movimiento": "Las manos parten de un mismo punto y luego se abren hacia los lados y hacia abajo mientras los dedos se extienden.", "rasgos_no_manuales": "Ojos semicerrados, labios protruidos.", "definicion": "v. tr. Dejar de tener algo, no saber dónde quedó una cosa que se tenía o alguna persona con la que se estaba, no conseguir algo que se esperaba.", "pagina": 333}', ARRAY['Perder']::text[], 'v. tr. Dejar de tener algo, no saber dónde quedó una cosa que se tenía o alguna persona con la que se estaba, no conseguir algo que se esperaba.'),
(990, 'SM', '{"codigo": "O-67", "significado": "Perfume", "tipo_sena": "SM", "configuracion": "Seña que pasa de O.9 a 5.1", "orientacion": "Palma hacia adentro.", "ubicacion": "La mano inicia sobre la nariz y termina sobre el pecho.", "movimiento": "Recto hacia abajo.", "rasgos_no_manuales": "Cabeza inclinada hacia atrás aspirando profundamente.", "definicion": "sust. f. Sustancia que generalmente se prepara con esencia de flores u otros vegetales y se emplea para dar buen olor a algo o a alguien.", "pagina": 334}', ARRAY['Perfume']::text[], 'sust. f. Sustancia que generalmente se prepara con esencia de flores u otros vegetales y se emplea para dar buen olor a algo o a alguien.'),
(991, 'SB', '{"codigo": "O-68", "significado": "Poner", "tipo_sena": "SB", "configuracion": "MD O.5, MB S.1", "orientacion": "MD y MB palmas hacia abajo.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "La MD simula un salto.", "definicion": "v. tr. Hacer que algo o alguien pase a estar o quede en cierto lugar, posición, circunstancia o estado.", "pagina": 334}', ARRAY['Poner']::text[], 'v. tr. Hacer que algo o alguien pase a estar o quede en cierto lugar, posición, circunstancia o estado.'),
(992, 'SB', '{"codigo": "O-69", "significado": "Poner 1 / Llenar el formato2 (B)", "tipo_sena": "SB", "configuracion": "MD O.5, MB B-P.2", "orientacion": "MD palma hacia la izquierda, MB palma hacia la derecha.", "ubicacion": "La MD inicia sobre los dedos de MB y termina sobre su muñeca. MB a la altura del cuello.", "movimiento": "La MD simula varios saltos.", "definicion": "1. v. tr. Escribir algo en el papel. 2. v. tr. Escribir o marcar los datos que se piden o se requieren en un pos-MI PAPÁ documento, en un formulario o en algo similar.", "pagina": 334}', ARRAY['Poner', 'Llenar el formato']::text[], '1. v. tr. Escribir algo en el papel. 2. v. tr. Escribir o marcar los datos que se piden o se requieren en un pos-MI PAPÁ documento, en un formulario o en algo similar.'),
(993, 'SC', '{"codigo": "O-70", "significado": "Pórtate bien – Compórtate", "tipo_sena": "SC: I. SB; II. SM", "configuracion": "I. MD O.5, MB S.1; II. B-P.2", "orientacion": "I. MD y MB palmas hacia abajo; II. Palma hacia adentro.", "ubicacion": "I. MD inicia a la altura de los hombros y termina sobre MB. MB a la altura del pecho; II. Sobre la barbilla.", "movimiento": "I. La MD se mueve formando un arco; II. Recto hacia el frente.", "definicion": "v. intr. Orden con la que se mandata a alguien a actuar bien o de manera correcta.", "nota_cultural": "Se trata de la seña PONER más la seña BIEN .", "pagina": 335}', ARRAY['Pórtate bien', 'Compórtate']::text[], 'v. intr. Orden con la que se mandata a alguien a actuar bien o de manera correcta.'),
(994, 'SS', '{"codigo": "O-71", "significado": "Prender – Encender", "tipo_sena": "SS", "configuracion": "Seña que pasa de O.5 a 5.1", "orientacion": "Palmas hacia fuera.", "ubicacion": "A la altura del pecho.", "movimiento": "Los dedos se extienden.", "rasgos_no_manuales": "Cejas hacia arriba.", "definicion": "v. tr. Poner a funcionar un aparato o mecanismo que trabaja generalmente con electricidad o gas.", "pagina": 335}', ARRAY['Prender', 'Encender']::text[], 'v. tr. Poner a funcionar un aparato o mecanismo que trabaja generalmente con electricidad o gas.'),
(995, 'SB', '{"codigo": "O-72", "significado": "Pretexto – Excusa (A)", "tipo_sena": "SB", "configuracion": "MD seña que pasa de O.5 a 5.2, MB B-P.2", "orientacion": "MD palma hacia la izquierda. MB palma hacia abajo.", "ubicacion": "La MD inicia debajo de MB y termina a la altura de la cintura, del centro al lado izquierdo. MB a la altura del pecho.", "movimiento": "El brazo de MD se mueve formando un arco mientras los dedos se extienden.", "rasgos_no_manuales": "Boca abierta y mostrando los dientes.", "definicion": "sust.Circunstancia que alguien alega como justificación o causa de su comportamiento y que en realidad no existió o no tuvo que ver con lo que hizo.", "pagina": 335}', ARRAY['Pretexto', 'Excusa']::text[], 'sust.Circunstancia que alguien alega como justificación o causa de su comportamiento y que en realidad no existió o no tuvo que ver con lo que hizo.'),
(996, 'SB', '{"codigo": "O-73", "significado": "Pretexto – Excusa (B)", "tipo_sena": "SB", "configuracion": "MD y MB O.5", "orientacion": "MD y MB palmas hacia abajo.", "ubicacion": "MD y MB a la altura del pecho.", "movimiento": "MD y MB se mueven formando círculos alternadamente", "rasgos_no_manuales": "Ceño fruncido, ojos semicerrados, la punta de la lengua fuera.", "definicion": "sust. Circunstancia que alguien alega como justificación o causa de su comportamiento y que en realidad no existió o no tuvo que ver con lo que hizo.", "pagina": 336}', ARRAY['Pretexto', 'Excusa']::text[], 'sust. Circunstancia que alguien alega como justificación o causa de su comportamiento y que en realidad no existió o no tuvo que ver con lo que hizo.'),
(997, 'SM', '{"codigo": "O-74", "significado": "Sabio, bia 1/ Sabiduría2", "tipo_sena": "SM", "configuracion": "O.5", "orientacion": "Palma hacia adentro.", "ubicacion": "A la altura de la frente.", "movimiento": "La mano se mueve de atrás hacia adelante flexionando sòlo la muñeca.", "definicion": "1. adj. y sust. Que tiene conocimientos profundos de algo. 2. sust. f. Conjunto de los conocimientos profundos de la vida y la naturaleza que permite la comprensión general de las cosas y de las acciones, y la elaboración de juicios claros, generosos y prudentes.", "pagina": 336}', ARRAY['Sabio', 'Sabiduría']::text[], '1. adj. y sust. Que tiene conocimientos profundos de algo. 2. sust. f. Conjunto de los conocimientos profundos de la vida y la naturaleza que permite la comprensión general de las cosas y de las acciones, y la elaboración de juicios claros, generosos y prudentes.'),
(998, 'SB', '{"codigo": "O-75", "significado": "Salir1 / Salida2", "tipo_sena": "SB", "configuracion": "MD seña que pasa de O.5 a 5.2, MB C.1", "orientacion": "MD y MB palmas hacia arriba.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "MD recto hacia el frente.", "definicion": "1. v. intr. Pasar de la parte interior de algo a la exterior o de adentro hacia afuera. 2. sust. f. Acto de salir o salirse.", "pagina": 336}', ARRAY['Salir', 'Salida']::text[], '1. v. intr. Pasar de la parte interior de algo a la exterior o de adentro hacia afuera. 2. sust. f. Acto de salir o salirse.'),
(999, 'SM', '{"codigo": "O-76", "significado": "San Judas", "tipo_sena": "SM", "configuracion": "Seña que pasa de O.1 a 5.2", "orientacion": "Palma hacia fuera.", "ubicacion": "Sobre la frente.", "movimiento": "Los dedos se extienden repetidamente.", "rasgos_no_manuales": "Cabeza inclinada hacia la derecha.", "definicion": "Uno de los discípulos de Jesús, que formaba parte del grupo de los doce apóstoles.", "pagina": 337}', ARRAY['San Judas']::text[], 'Uno de los discípulos de Jesús, que formaba parte del grupo de los doce apóstoles.'),
(1000, 'SB', '{"codigo": "O-77", "significado": "Secreto", "tipo_sena": "SB", "configuracion": "MD O.5, MB O.1", "orientacion": "MD palma hacia abajo. MB palma hacia adentro.", "ubicacion": "La MD inicia a la altura del pecho y termina detrás de MB. MB a la altura del abdomen.", "movimiento": "MD recto.", "definicion": "sust. m. Conocimiento de algo que alguien mantiene oculto o que sólo es compartido por un número reducido de personas; cosa que no se hace pública, se disimula o disfraza para evitar que se descubra, conozca o divulgue.", "pagina": 337}', ARRAY['Secreto']::text[], 'sust. m. Conocimiento de algo que alguien mantiene oculto o que sólo es compartido por un número reducido de personas; cosa que no se hace pública, se disimula o disfraza para evitar que se descubra, conozca o divulgue.'),
(1001, 'SB', '{"codigo": "O-78", "significado": "Sembrar", "tipo_sena": "SB", "configuracion": "MD seña que pasa de O.1 a 5.2, MB 5.11", "orientacion": "MD palma hacia abajo. MB palma hacia arriba.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "La MD se mueve formando un arco hacia el frente.", "representacion": "Simula la acción de esparcir semillas.", "definicion": "v. tr. Poner semillas de alguna planta o repartirlas en cierta cantidad y orden en la tierra que se va a cultivar.", "pagina": 337}', ARRAY['Sembrar']::text[], 'v. tr. Poner semillas de alguna planta o repartirlas en cierta cantidad y orden en la tierra que se va a cultivar.'),
(1002, 'SC', '{"codigo": "O-79", "significado": "Sumiso, sa", "tipo_sena": "SC: I. SM; II. SB", "configuracion": "I. O.5; II. MD y MB B-P.7", "orientacion": "I. Palma hacia adentro; II. MD y MB palmas hacia abajo.", "ubicacion": "I. La mano inicia sobre la barbilla y termina sobre el pecho; II. MD sobre la muñeca de MB. MB a la altura del pecho.", "movimiento": "I. La mano simula un salto; II. MD y MB recto hacia abajo.", "rasgos_no_manuales": "Cabeceo en diagonal.", "definicion": "adj. Que acepta la autoridad o el poder de alguien con extrema obediencia y sin protestar.", "pagina": 338}', ARRAY['Sumiso']::text[], 'adj. Que acepta la autoridad o el poder de alguien con extrema obediencia y sin protestar.'),
(1003, NULL, '{"codigo": "O-80", "significado": "Todavía – Aún", "tipo_sena": "MB", "configuracion": "MD O.5, MB B-P.2", "orientacion": "MD palma hacia abajo, MB palma hacia arriba.", "ubicacion": "A la altura del pecho. MD sobre MB.", "movimiento": "La MD golpea la palma de MB repetidamente.", "definicion": "adv. Hasta este momento o hasta cierto momento.", "pagina": 338}', ARRAY['Todavía', 'Aún']::text[], 'adv. Hasta este momento o hasta cierto momento.'),
(1004, 'SS', '{"codigo": "O-81", "significado": "Tubo", "tipo_sena": "SS", "configuracion": "O.1", "orientacion": "Palmas hacia abajo.", "ubicacion": "A la altura del pecho del centro a los lados.", "movimiento": "Las manos parten de un mismo punto y luego se abren hacia los lados.", "definicion": "sust. m. Cilindro largo y hueco a veces abierto por sus extremos, a veces cerrado por uno de ellos, que sirve para dejar correr o para contener líquidos, gases, sustancias cremosas, etc.", "pagina": 338}', ARRAY['Tubo']::text[], 'sust. m. Cilindro largo y hueco a veces abierto por sus extremos, a veces cerrado por uno de ellos, que sirve para dejar correr o para contener líquidos, gases, sustancias cremosas, etc.'),
(1005, 'SS', '{"codigo": "O-82", "significado": "Vivir 1 / Vida 2", "tipo_sena": "SS", "configuracion": "O.5", "orientacion": "Palmas hacia arriba.", "ubicacion": "Las manos inician sobre el abdomen y se deslizan hacia el pecho.", "movimiento": "Recto.", "definicion": "1. v. intr. Habitar en un determinado lugar o país. 2. sust. f. Estado de actividad de un ser vivo por el que se desarrolla, evoluciona y se reproduce.", "pagina": 339}', ARRAY['Vivir', 'Vida']::text[], '1. v. intr. Habitar en un determinado lugar o país. 2. sust. f. Estado de actividad de un ser vivo por el que se desarrolla, evoluciona y se reproduce.'),
(1006, 'SS', '{"codigo": "O-83", "significado": "Yo no fui (A)", "tipo_sena": "SS", "configuracion": "O.1", "orientacion": "Las palmas inician hacia fuera y terminan hacia adentro.", "ubicacion": "A la altura de los hombros.", "movimiento": "Los antebrazos giran y cambian la orientación de las manos, pasan de mostrar las palmas a mostrar los dorsos.", "rasgos_no_manuales": "Labios protuidos.", "definicion": "loc. v. No haber hecho algo.", "pagina": 339}', ARRAY['Yo no fui']::text[], 'loc. v. No haber hecho algo.');
